# GU cards: UI kit, typography, HUD, RSAMH-style chrome, transitions and effects ("juice").
# Plan and palette: docs/art/GU.md. Every card is a small pure-JS module with a jsc test (tests/fakectx.js).
FK = "tests/fakectx.js (recording fake canvas: `ctx.calls` is a list of [method, args]; property sets are recorded as `set:<prop>`; `measureText(s).width` is `s.length * 0.6 * <px size in ctx.font>`; helpers `makeCtx, texts, count, lastSet, anySet, reset`) and tests/harness.js (`test, eq, ok, throws, done`; end every test file with `done();`)"
GUD = "docs/art/GU.md (the plan: palette, type scale, spacing grid, motion timings, zones) and docs/art/RSAMH_STYLE.md (the look we echo)"
THEME = "src/ui/theme.js (exports `PALETTE`, `font(kind, px)`, `shade(hex, amount)`, `rgba(hex, alpha)`; do not edit it)"
TOK = "src/ui/tokens.js (card GU01: `COLOR`, `SPACE`, `ZONES`, `TYPE`, `FLOOR`, `MOTION`, `EASE`, `lerp`, `clamp01`)"
NOEDIT = "No existing file is edited, so every existing test stays green."
RUN = "Run one test file with `$JSC -m tests/<name>.test.mjs` (JSC is set by `make test`; on this Mac it is /System/Library/Frameworks/JavaScriptCore.framework/Versions/Current/Helpers/jsc)."
PURE = "No DOM, no `Math.random`, no `Date`: time comes in as a `nowMs` argument, randomness from a seeded integer hash."

