CARDS = [

 dict(id="GU01", title="UI tokens: colours, spacing, type scale, motion, easing", needs=[],
  files=["src/ui/tokens.js", "tests/tokens.test.mjs"],
  goal="One file holding every number of the new UI language (palette additions, 4px spacing grid, the three screen zones, type scale with phone-safe minimum sizes, motion timings, easing functions) so later cards never invent numbers.",
  read=[GUD, THEME, FK],
  steps=[
   "`src/ui/tokens.js` (ES module, no imports needed except `font` from './theme.js'). Export `COLOR`, a frozen-style plain object with EXACTLY these 29 keys: ink '#14102A', night '#1B1735', well '#241E45', wood '#6B4423', woodLight '#8C5E34', woodDark '#3F2814', woodGrain '#4E3119', brass '#C9A24A', brassLight '#F2D98A', brassDark '#8A6B1F', enamelRed '#B3282D', enamelGreen '#1E5A3C', enamelNavy '#1C2E5A', paper '#FFF7DC', paperShade '#D9CBA0', paperFold '#C2B183', bannerTop '#F6CFA0', bannerBottom '#D9A66F', bannerDither '#C48B55', hudBg '#1B1735', hudEdge '#0B0818', chartWhite '#F8F6EE', cashGreen '#3FAE49', cashDark '#1F6B2E', rivet '#C9CCD2', phosphor '#7CFF8A', amber '#FFB84D', warn '#F2A93B', info '#70A4B2'.",
   "Export `SPACE` = {1:4, 2:8, 3:12, 4:16, 5:24, 6:32, 7:48} and `sp(n)` returning SPACE[n] (throw Error('bad space') for any other n). Export `ZONES` = {banner:{x:0,y:0,w:1280,h:120}, tableau:{x:0,y:120,w:1280,h:470}, hud:{x:0,y:590,w:1280,h:130}}. Export `FLOOR` = {title:16, body:22} (smallest allowed px per font kind: on an iPhone held landscape the 1280x720 canvas is scaled by about 0.55, so 22px VT323 is about 12 CSS px and 16px Press Start 2P about 9 CSS px). Export `TYPE` = {logo:{kind:'title',px:64}, h1:{kind:'title',px:32}, h2:{kind:'title',px:24}, h3:{kind:'title',px:16}, button:{kind:'title',px:16}, bannerText:{kind:'title',px:16,lineH:28}, hero:{kind:'body',px:40}, body:{kind:'body',px:28}, caption:{kind:'body',px:24}}. Export `fontFor(role)` = font(TYPE[role].kind, TYPE[role].px) (throw Error('bad role') when unknown).",
   "Export `MOTION` (milliseconds) = {tap:90, press:80, toast:260, toastHold:2500, toastOut:200, bar:450, count:700, page:320, slide:350, fade:250, iris:500, static:400, flip:700, shake:300, flash:180, dayChange:2400}. Export `clamp01(u)`, `lerp(a, b, u)` = a + (b - a) * u, and `EASE` = {linear, outQuad, outCubic, inOutQuad, outBack, outBounce}, each a function of u in 0..1 (callers clamp): outQuad = 1-(1-u)^2; outCubic = 1-(1-u)^3; inOutQuad = u<0.5 ? 2u^2 : 1-(-2u+2)^2/2; outBack uses c1=1.70158, c3=c1+1: 1 + c3*(u-1)^3 + c1*(u-1)^2; outBounce is the standard four-segment bounce (n1=7.5625, d1=2.75). Also export `ease(name, u)` = EASE[name](clamp01(u)), throwing Error('bad ease') for an unknown name.",
   "`tests/tokens.test.mjs`: assert COLOR has 29 keys and every value matches /^#[0-9A-Fa-f]{6}$/; spot-check exact values for ink, brass, bannerTop, cashGreen; `sp(3)` is 12 and `sp(9)` throws; ZONES heights add up (banner.h + tableau.h + hud.h === 720) and each zone starts where the previous ends; `fontFor('button')` is '16px \"Press Start 2P\", monospace'; `fontFor('body')` is '28px VT323, monospace'; for every name in EASE, f(0) is 0 and f(1) is 1 within 1e-9 (outBack(0) may be 2.2e-16: use a tolerance); outQuad(0.5)=0.75, outCubic(0.5)=0.875, inOutQuad(0.25)=0.125, outBack(0.5) within 1e-6 of 1.0876975; `ease('outCubic', 2)` is 1 and `ease('outCubic', -1)` is 0; `ease('nope', 0)` throws."],
  accept=["`make test 2>&1 | grep 'PASS tests/tokens.test.mjs'` prints one line.", NOEDIT],
  oos=["src/ui/theme.js and every other existing file."]),

 dict(id="GU02", title="Text-fit helpers so nothing overlaps or clips", needs=["GU01"],
  files=["src/ui/textfit.js", "tests/textfit.test.mjs"],
  goal="Pure helpers that choose a font size and wrap lines so text fits a box (numbers, not eyeballing), plus a helper that fits a picture into a rectangle. Used by every later card and by the scene fixes.",
  read=[GUD, TOK, THEME, FK, "src/ui/kit_draw.js (see `label` and `wrapLines`; the new file must NOT import kit_draw.js, because kit_draw will later re-export this file: copy the small greedy word-wrap idea into a private function)"],
  steps=[
   "`src/ui/textfit.js` imports `font` from './theme.js' and `FLOOR` from './tokens.js'. Private `wrap(ctx, text, maxW, fontStr)` -> string[] (greedy by spaces, newline starts a paragraph, a word wider than maxW gets its own line). Export `ellipsize(ctx, text, maxW, fontStr)`: set `ctx.font = fontStr`; return text unchanged when `ctx.measureText(text).width <= maxW`; else the longest prefix p (cut from the end one char at a time) such that `p + '...'` fits (ASCII three dots); '' when even '...' does not fit.",
   "Export `fitOne(ctx, text, maxW, opts)`: opts {kind:'body', maxPx:28, minPx: FLOOR[kind]}. Try px = maxPx, maxPx-1 ... minPx and return the first {px, text, w, truncated:false} whose measured width (with `font(kind, px)` set) is <= maxW. If none fits, return {px:minPx, text: ellipsize(...at minPx), w:<measured>, truncated:true}. Export `fitBlock(ctx, text, w, h, opts)`: opts {kind:'body', maxPx:28, minPx: FLOOR[kind], lineRatio:1.1, maxLines:Infinity}. For px from maxPx down to minPx: lines = wrap(...), lineH = Math.round(px*lineRatio); accept the first px with lines.length <= maxLines and lines.length*lineH <= h and every line width <= w; return {px, lines, lineH, h: lines.length*lineH, truncated:false}. If none fits: at minPx keep only the lines that fit (min(maxLines, floor(h/lineH)), at least 1), ellipsize the last kept line to w, return truncated:true.",
   "Export `drawFitted(ctx, text, rect, opts)`: runs fitBlock(rect.w, rect.h, opts) then draws each line with ctx.fillText at x = rect.x (align 'left'), rect.x + rect.w/2 (opts.align 'center') or rect.x + rect.w (opts.align 'right'), y = rect.y + i*lineH (+ (rect.h - result.h)/2 when opts.valign is 'middle'), `textBaseline 'top'`, fillStyle opts.color (default '#14102A'); returns the fitBlock result. Export `fitInRect(srcW, srcH, rect, opts)`: opts {maxScale: Infinity, pad: 8}; scale = Math.min(maxScale, (rect.w - 2*pad)/srcW, (rect.h - 2*pad)/srcH); return {scale, x: rect.x + rect.w/2 (centre), y: rect.y + rect.h - pad (bottom, where a car's ground point goes), w: srcW*scale, h: srcH*scale}.",
   "`tests/textfit.test.mjs` (numbers use the fake ctx width rule 0.6*px per char): fitOne(ctx,'Hello',100,{kind:'body',maxPx:28}) gives px 28 (5*16.8=84 <= 100) and w 84; fitOne(ctx,'A'.repeat(20),100,{kind:'body',maxPx:28}) gives px 22, truncated true, text 'AAAA...' (check: (4+3)*13.2=92.4 <= 100 and 8 chars would be 145); fitOne(ctx,'A'.repeat(5),100,{kind:'title',maxPx:24}) gives px 24 (72 wide); ellipsize(ctx,'abcdefghij',60,'20px X') is 'ab...' (each char is 12px: 5 chars = 60) and ellipsize(ctx,'abc',60,'20px X') is 'abc'; fitBlock for 'aaa bbb ccc ddd eee fff' in w 130 h 200 with maxPx 28: assert every line width <= 130, lines.length*lineH <= 200, truncated false; fitBlock with h 24 and maxPx 22 minPx 22 on a long text returns truncated true, lines.length 1 and the last line ends with '...'; drawFitted draws exactly lines.length fillText calls and none at y outside rect.y..rect.y+rect.h; fitInRect(480,170,{x:0,y:0,w:600,h:170},{pad:10,maxScale:1.15}) gives scale within 1e-9 of 150/170, x 300, y 160."],
  accept=["`make test 2>&1 | grep 'PASS tests/textfit.test.mjs'` prints one line.", NOEDIT],
  oos=["src/ui/kit_draw.js (GU21 wires this in)."]),

 dict(id="GU03", title="UI audit helper: text boxes, minimum sizes, overlaps", needs=["GU01"],
  files=["tests/uiaudit.js", "tests/uiaudit.test.mjs"],
  goal="A TEST helper (not game code) that replays a fakectx call log and reports every text box with its size, so tests can assert numerically: no text below the phone-safe minimum, no text off the canvas, no two texts overlapping. This is how Lee's complaints (overlapping and clipped text) become failing tests.",
  read=[TOK, FK, "tests/scene_tvshop_draw.test.mjs (how a scene is drawn against a fake ctx)"],
  steps=[
   "`tests/uiaudit.js` (plain ES module; imports `FLOOR` from '../src/ui/tokens.js'). Export `replayTexts(ctx)` -> array of entries {text, x0, y0, x1, y1, px, kind, align, baseline, transformed}. Walk `ctx.calls` in order keeping the current font, textAlign, textBaseline (defaults '10px sans-serif', 'left', 'alphabetic'), a translate offset (tx,ty) and a save/restore stack of all of those. `set:font` etc update state; `save` pushes, `restore` pops; `translate(dx,dy)` adds to the offset; `scale`, `rotate`, `transform`, `setTransform` set a flag `transformed` true until the matching restore. On `fillText`/`strokeText` (text, x, y): px = first number before 'px' in the font string; kind = 'title' when the font contains 'Press Start 2P', 'body' when it contains 'VT323', else 'other'; w = text.length*0.6*px (the fakectx rule); h = px; x0 by align (left: x; center: x - w/2; right: x - w); y0 by baseline (top: y; middle: y - h/2; bottom: y - h; alphabetic or anything else: y - 0.8*h); add the translate offset; x1 = x0+w, y1 = y0+h.",
   "Export `auditCtx(ctx, opts)` with opts {w:1280, h:720, ignoreShadowOffset:4}: entries = replayTexts(ctx) without the `transformed` ones; return {entries, belowFloor, offCanvas, overlaps}. belowFloor = entries whose kind is 'title' or 'body' and px < FLOOR[kind]. offCanvas = entries with x0 < 0 or y0 < 0 or x1 > w or y1 > h. overlaps = array of [a, b] entry pairs (a before b in call order) whose boxes intersect with intersection area > 4 px^2, EXCEPT pairs with the identical text string whose x0 and y0 each differ by <= ignoreShadowOffset (a drop shadow or a 4-way outline, not an overlap). Also export `rectsOverlap(a, b)` for {x,y,w,h} rectangles (true when the intersection area > 0) and `describe(entry)` -> 'text@x0,y0 px' for readable failure messages.",
   "`tests/uiaudit.test.mjs`: build ctx with makeCtx; set `ctx.font = '16px \"Press Start 2P\", monospace'`, `ctx.textBaseline = 'top'`, `ctx.fillText('ABCD', 10, 20)` and assert one entry with px 16, kind 'title', w 38.4 (4*0.6*16), x0 10, y0 20, x1 48.4, y1 36; center align at x 100 gives x0 = 100 - w/2; baseline 'middle' at y 50 gives y0 = 50 - px/2; font '14px VT323, monospace' is below the body floor (22) and appears in belowFloor, '22px VT323, monospace' does not; a text at x 1270 with w > 10 is in offCanvas; two different strings 8px apart vertically at the same x overlap (overlaps.length 1) while the same string drawn twice with a (+2,+2) offset does not, and the same string drawn at (x-2,y) and (x+2,y) (a 4px outline spread) does not either; a translate(100,0) before a text at x 10 gives x0 110; text drawn between `scale` and the matching `restore` is excluded from entries; rectsOverlap({x:0,y:0,w:10,h:10},{x:10,y:0,w:5,h:5}) is false and with x:9 is true."],
  accept=["`make test 2>&1 | grep 'PASS tests/uiaudit.test.mjs'` prints one line.", "`grep -c 'export function' tests/uiaudit.js` prints 4 or more.", NOEDIT],
  oos=["Game code under src/. This card adds only test files."]),

 dict(id="GU04", title="Icon set drawn in code: 14 icons plus 4 plate discs", needs=["GU01"],
  files=["src/ui/icons.js", "tests/icons.test.mjs"],
  goal="Pixel icons stored as text bitmaps and drawn with merged fillRect runs: money, rep star, buzz bolt, calendar, wrench, key, telephone, newspaper, tick, cross, padlock, warning, fuel can, tyre, and the four Gold Number Plate discs (fat cat, stable horseshoe, household house, hammer mallet). Designed by the planner and checked by eye already: copy the bitmaps EXACTLY.",
  read=[GUD, TOK, FK],
  steps=[
   "`src/ui/icons.js` (no imports needed). Const `ICON_DATA`: each entry is `name: 12 rows` (utility icons, 12x12 cells) or `16 rows` (plate_* icons, 16x16 cells), rows separated by `|`, a '.' is transparent. Copy EXACTLY (one string per name, any quoting you like):\n" + UTIL_BITMAPS + "\n" + PLATE_BITMAPS + "\nSplit each string on '|' into a rows array once at module load. Export `ICON_NAMES` = the 18 names in the order listed above (coin, star, buzz, calendar, wrench, key, phone, paper, tick, cross, padlock, warning, fuel, tyre, plate_fatcat, plate_stable, plate_household, plate_hammer).",
   "Const `ICON_PAL` mapping the letters to colours: o '#14102A', w '#FFFFFF', y '#E8B923', Y '#FFE27A', d '#A57A12', g '#3FAE49', G '#1F6B2E', r '#D9483B', R '#8E2A22', l '#C9CCD2', k '#6C6C6C', c '#F4E9C8', m '#F2A93B'. Grey variant (used for plates not yet won): when opts.grey is true map Y -> '#B8B8B8', y -> '#959595', d -> '#6C6C6C' (all other letters unchanged).",
   "Export `iconCells(name)` -> number of non-'.' cells (throw Error('bad icon') for an unknown name) and `iconSize(name)` -> 12 or 16. Export `drawIcon(ctx, name, x, y, size, opts)`: opts {alpha:1, grey:false}; cell = size / iconSize(name); for each row, merge horizontal runs of the SAME letter into one `ctx.fillRect(x + cx*cell, y + row*cell, runLen*cell, cell)`, setting `ctx.fillStyle` only when the colour differs from the previous run; when opts.alpha < 1 wrap everything in save, `globalAlpha = alpha`, restore. Returns nothing.",
   "`tests/icons.test.mjs`: ICON_NAMES has 18 entries; iconCells equals this exact table (a transcription check): coin 108, star 72, buzz 63, calendar 130, wrench 68, key 69, phone 114, paper 120, tick 50, cross 64, padlock 100, warning 102, fuel 106, tyre 116, plate_fatcat 208, plate_stable 208, plate_household 208, plate_hammer 208. Every row of every icon has the right length (12 or 16) and the right row count. drawIcon(ctx,'coin',0,0,24) makes exactly 55 fillRect calls (runs), 'cross' 44, 'tick' 40, 'star' 43; every fillRect lies inside [0,24] x [0,24]; every fillStyle used is a value of ICON_PAL. drawIcon(ctx,'plate_hammer',100,50,48) uses cell 3 (some fillRect has height 3) and stays inside [100,148] x [50,98]; with {grey:true} the fillStyles include '#B8B8B8' and not '#FFE27A'; without grey they include '#FFE27A'. drawIcon with alpha 0.5 sets globalAlpha 0.5 then back (last `set:globalAlpha` is 1 or restore is called). drawIcon(ctx,'nope',0,0,12) throws."],
  accept=["`make test 2>&1 | grep 'PASS tests/icons.test.mjs'` prints one line.", NOEDIT],
  oos=["Any scene or HUD (later cards use the icons)."]),

 dict(id="GU05", title="Textured panels: chunky frame, paper, wood plank, enamel sign", needs=["GU01"],
  files=["src/ui/panels2.js", "tests/panels2.test.mjs"],
  goal="The panel recipes of the new look: pixel-stepped corners, 3px ink edge, hard drop shadow, top-left highlight and bottom-right shade, then a material on top (paper grain, wood planks with grain streaks, enamel sign with rivets and gloss). Pure fillRect recipes with exact coordinates so tests can check them.",
  read=[GUD, TOK, THEME, FK],
  steps=[
   "`src/ui/panels2.js` imports `COLOR` from './tokens.js'. Export `chunkyRect(ctx, x, y, w, h, fill, cut = 3)`: set `ctx.fillStyle = fill` once, then exactly three fillRects in this order: (x+cut, y, w-2*cut, h), (x, y+cut, w, h-2*cut), (x+1, y+1, w-2, h-2). Export `chunkyPanel(ctx, x, y, w, h, opts)`: opts {fill: COLOR.paper, edge: COLOR.ink, bw: 3, cut: 3, shadow: 4, hi: true}. Order: (1) when shadow > 0: chunkyRect(x+shadow, y+shadow, w, h, 'rgba(0,0,0,0.35)', cut); (2) chunkyRect(x, y, w, h, edge, cut); (3) chunkyRect(x+bw, y+bw, w-2*bw, h-2*bw, fill, Math.max(1, cut-1)); (4) when hi: fillStyle 'rgba(255,255,255,0.35)' then fillRect(x+bw+cut, y+bw, w-2*bw-2*cut, 2) and fillRect(x+bw, y+bw+cut, 2, h-2*bw-2*cut); fillStyle 'rgba(0,0,0,0.22)' then fillRect(x+bw+cut, y+h-bw-2, w-2*bw-2*cut, 2) and fillRect(x+w-bw-2, y+bw+cut, 2, h-2*bw-2*cut). Return the content rect {x: x+bw+4, y: y+bw+4, w: w-2*(bw+4), h: h-2*(bw+4)}.",
   "Export `grain(ctx, x, y, w, h, color, density, seed)`: n = Math.floor(w*h*density); s = seed >>> 0; fillStyle = color once; repeat n times: s = (Math.imul(s, 1664525) + 1013904223) >>> 0; px = x + (s % (w-2)); s = (Math.imul(s, 1664525) + 1013904223) >>> 0; py = y + (s % (h-2)); ctx.fillRect(px, py, 2, 2). Export `paperPanel(ctx, x, y, w, h, opts)`: chunkyPanel with fill COLOR.paper (opts may override fill, edge, shadow); then grain over the returned content rect with color 'rgba(20,16,42,0.06)', density 1/500, seed ((x*31 + y*17) & 0xffff); return the content rect.",
   "Export `woodPanel(ctx, x, y, w, h, opts)`: chunkyPanel with fill COLOR.wood; then with the content rect c: planks = Math.ceil(c.h/28); for k = 1..Math.floor((c.h-1)/28): fillStyle COLOR.woodDark, fillRect(c.x, c.y + 28*k, c.w, 2); for every plank p in 0..planks-1 and j in 0..2: sx = hash from (p*7+j+1) using the same LCG as grain (one step from seed p*7+j+1), fillStyle COLOR.woodGrain, fillRect(c.x + (sx % (c.w-40)), c.y + 28*p + 6 + j*8, 24 + (sx % 32), 1). Require c.w > 40 (else skip the streaks). Return c. Export `enamelSign(ctx, x, y, w, h, opts)`: opts {color: COLOR.enamelRed, text: null, textColor: '#FFFFFF'}: chunkyPanel with fill = color; a cream keyline '#F4E9C8' as four 2px fillRects inset 10 (top (x+10,y+10,w-20,2), bottom (x+10,y+h-12,w-20,2), left (x+10,y+10,2,h-20), right (x+w-12,y+10,2,h-20)); four rivets as `ctx.arc(cx, cy, 2.5, 0, Math.PI*2)` + fill with COLOR.rivet at (x+7,y+7), (x+w-7,y+7), (x+7,y+h-7), (x+w-7,y+h-7); a gloss polygon filled 'rgba(255,255,255,0.12)': moveTo (x+bw,y+bw), lineTo (x+w*0.55,y+bw), lineTo (x+w*0.25,y+h-bw), lineTo (x+bw,y+h-bw), closePath, fill (bw = 3). When opts.text is set: font '16px \"Press Start 2P\", monospace', textAlign 'center', textBaseline 'middle', fillStyle textColor, fillText at (x+w/2, y+h/2). Return the content rect.",
   "`tests/panels2.test.mjs`: chunkyRect(ctx,10,10,100,50,'#f00',3) -> exactly 3 fillRect calls equal to [13,10,94,50], [10,13,100,44], [11,11,98,48] in that order; chunkyPanel(ctx,10,20,100,60) -> 13 fillRect calls in total, the first is [17,24,94,60] (the shadow), and it returns {x:17,y:27,w:86,h:46}; with {shadow:0} 10 calls; grain(ctx,0,0,200,90,'#000',1/600,5) -> exactly 30 fillRect calls, each [px,py,2,2] with 0<=px<=198, 0<=py<=88, and calling it twice gives identical call lists; paperPanel(ctx,10,20,100,60) -> 13 + Math.floor(86*46/500) = 20 fillRects; woodPanel(ctx,10,20,100,100) -> chunkyPanel's 13 + 3 plank lines (h 86 -> floor(85/28)) + 12 streaks = 28 fillRects, and the plank lines are the fillRects with fillStyle COLOR.woodDark; enamelSign(ctx,0,0,200,80,{text:'GARAGE'}) -> exactly 4 `arc` calls, one fillText 'GARAGE' at (100,40), a closePath; for each of the four panels every fillRect and arc lies inside [x-1, x+w+5] x [y-1, y+h+5] (the 4px shadow is the farthest thing drawn)."],
  accept=["`make test 2>&1 | grep 'PASS tests/panels2.test.mjs'` prints one line.", NOEDIT],
  oos=["src/ui/kit_draw.js (GU21 wires the panels in)."]),

 dict(id="GU06", title="Chunky button with hover/press states, plus press and hover sound hooks", needs=["GU01", "GU02", "GU04", "GU05"],
  files=["src/ui/button2.js", "src/ui/uistate.js", "tests/button2.test.mjs"],
  goal="A bevelled arcade button that visibly presses down (face drops 3px) and brightens on hover, with the label centred by formula (fixes labels sitting too high), and a tiny state tracker that fires `app.audio.play('hover'|'tap'|'click'|'deny')` hooks. Pure: the scene still owns hits.",
  read=[GUD, TOK, THEME, FK, "src/ui/kit_draw.js (the existing `button` and its tests in tests/kit_draw.test.mjs: disabled = midgrey fill + darkgrey label, hot = lamp strokeStyle; GU21 will make `button` call the new one)", "src/ui/kit_hits.js (hit entries are {id,x,y,w,h,onTap,enabled})", "docs/SCENE_RULES.md (TAP RULE: pressed state is reset only on 'up', never in draw)"],
  steps=[
   "`src/ui/button2.js` (imports panels2 chunkyRect, textfit fitOne, icons drawIcon, theme PALETTE/shade, tokens COLOR; must NOT import kit_draw.js). Export `drawButton2(ctx, b, st)`: b = {x,y,w,h,label,enabled=true,hot=false,kind='normal'|'primary'|'danger'|'gold',icon}, st = {hover:false, pressed:false}. fill by kind: normal PALETTE.lightblue, primary PALETTE.good, danger PALETTE.bad, gold COLOR.brass; disabled: PALETTE.midgrey; hover (and enabled, not pressed): shade(fill, 0.12). d = pressed ? 3 : 0. Draw in this order: (1) when not pressed, shadow chunkyRect(x+4, y+4, w, h, 'rgba(0,0,0,0.35)', 4); (2) edge chunkyRect(x, y, w, h, COLOR.ink, 4); (3) lip: fillStyle shade(fill, -0.35), fillRect(x+3, y+h-8, w-6, 5); (4) face: fillStyle fill, fillRect(x+3, y+3+d, w-6, h-11-d); (5) highlight: fillStyle shade(fill, 0.3), fillRect(x+3, y+3+d, w-6, 4); (6) label: size = Math.max(16, Math.min(24, Math.round(h*0.34))); r = fitOne(ctx, label, w-24-(icon?28:0), {kind:'title', maxPx:size}); font = `${r.px}px \"Press Start 2P\", monospace`, textAlign 'center', textBaseline 'middle', ly = y + d + Math.round((h-5)/2), lx = x + w/2 + (icon ? 14 : 0); unless disabled draw the text first in 'rgba(0,0,0,0.5)' at (lx+2, ly+2); then fillStyle (disabled ? PALETTE.darkgrey : PALETTE.white), fillText(r.text, lx, ly); (7) when icon: drawIcon(ctx, icon, x+12, y + d + Math.round((h-5)/2) - 12, 24); (8) when hot: lineWidth 3, strokeStyle PALETTE.lamp, strokeRect(x, y, w, h).",
   "`src/ui/uistate.js`: export `makeUi(app)` -> {hot:null, pressed:null, pointer(type, hit), state(id)}. `pointer('move', hit)`: id = hit && hit.enabled !== false ? hit.id : null; when id !== this.hot set hot = id and, when id is not null, play 'hover'. `pointer('down', hit)`: pressed = hit ? hit.id : null (remember the ID, not the object); when hit is enabled play 'tap', when hit exists but is disabled play 'deny'. `pointer('up', hit)`: committed = hit !== null && hit.enabled !== false && this.pressed !== null && hit.id === this.pressed; pressed = null; when committed play 'click'; return committed (true/false) so the scene can run onTap. `state(id)` -> {hover: id === this.hot, pressed: id === this.pressed}. Playing a sound = `if (app.audio && typeof app.audio.play === 'function' && !(app.settings && app.settings.sound === false)) app.audio.play(name)`. Nothing here resets `pressed` except 'up'.",
   "`tests/button2.test.mjs` (use tests/fakeapp.js `makeApp` for audio; its calls log is `app.calls` entries ['play', name]): normal 'START' button {x:10,y:10,w:120,h:40}: texts include 'START'; label fillText y is 10+0+Math.round(35/2)=28; the same button with st.pressed true draws the label at y 31 (exactly 3 lower) and has no shadow fillRect (the unpressed button's first fillRect is the shadow [18,14,112,40]; the pressed one's first fillRect is the edge [14,10,112,40]); fillStyles used include PALETTE.lightblue, shade(PALETTE.lightblue,0.3) and shade(PALETTE.lightblue,-0.35); kind 'primary' uses PALETTE.good; hover uses shade(PALETTE.lightblue,0.12) as the face; disabled uses PALETTE.midgrey for the face and PALETTE.darkgrey for the label; hot sets strokeStyle PALETTE.lamp; icon:'coin' adds drawIcon fillRects inside [x+12, x+36]; a button {x:0,y:0,w:120,h:64,label:'ABCDEFGH'} starts at size 22 and is drawn with font px 20 (96 = 8*0.6*20 fits w-24 = 96) while a 40-char label on the same button ends at px 16 with an ellipsis ('...' at the end of the drawn text). uistate: move over an enabled hit plays 'hover' once (moving again over the same id plays nothing); down on enabled plays 'tap'; up on the same id returns true and plays 'click'; up on a different id returns false and plays nothing; down on a disabled hit plays 'deny'; with app.settings.sound false nothing is played; calling `state` never changes `pressed`."],
  accept=["`make test 2>&1 | grep 'PASS tests/button2.test.mjs'` prints one line.", "`grep -c \"from './kit_draw.js'\" src/ui/button2.js src/ui/uistate.js` prints 0 for both files.", NOEDIT],
  oos=["src/ui/kit_draw.js (GU21)."]),

 dict(id="GU07", title="Animated counters and bars: tween, count-up, stat bar with ghost", needs=["GU01"],
  files=["src/ui/anim.js", "src/ui/bars.js", "tests/anim_bars.test.mjs"],
  goal="Time-driven (no timers) tweens for money count-up and stat bars that fill and drain, and a bar drawing recipe whose inner fill keeps the exact geometry of the old `bar` so scene tests stay green.",
  read=[GUD, TOK, THEME, FK, "src/ui/kit_draw.js (`bar` and its tests: bar(ctx,10,10,100,20,5,10,'#f00') must still make fillRect [12,12,48,16])"],
  steps=[
   "`src/ui/anim.js` (imports EASE, MOTION, clamp01, lerp from tokens). Export `makeTween(from, to, startMs, durMs, ease = 'outCubic')` -> {from,to,startMs,durMs,ease}; `tweenValue(tw, nowMs)`: u = durMs <= 0 ? 1 : clamp01((nowMs - startMs)/durMs); return lerp(from, to, EASE[ease](u)); `tweenDone(tw, nowMs)` = nowMs >= startMs + durMs. Export the counter: `makeCounter(v)` -> {tw: makeTween(v, v, 0, 0)}; `counterSet(c, target, nowMs, durMs = MOTION.count)` restarts the tween FROM the currently shown float value; `counterValue(c, nowMs)` = Math.round(tweenValue(c.tw, nowMs)). Export the bar animation: `makeBarAnim(frac)` -> {main: tween(frac,frac), ghost: tween(frac,frac)}; `barAnimSet(a, frac, nowMs)`: main = makeTween(current main value, frac, nowMs, MOTION.bar, 'outCubic'); when frac is lower than the current value the ghost keeps its current value, then drains: ghost = makeTween(current ghost value, frac, nowMs + 300, MOTION.bar, 'outCubic'); when frac is higher the ghost follows the main tween exactly (same start and duration); `barAnimValues(a, nowMs)` -> {value, ghost}.",
   "`src/ui/bars.js` (imports COLOR from tokens, shade from theme; must NOT import kit_draw.js). Export `drawBar2(ctx, x, y, w, h, value, max, color, opts)`: frac = max > 0 ? clamp(value/max, 0, 1) : 0; fw = (w-4)*frac (NOT rounded). Order: (1) fillStyle COLOR.well, fillRect(x, y, w, h); (2) fillStyle color, fillRect(x+2, y+2, fw, h-4); (3) when frac > 0: fillStyle shade(color, 0.35), fillRect(x+2, y+2, fw, 2); fillStyle shade(color, -0.3), fillRect(x+2, y+h-4, fw, 2); (4) segment ticks: fillStyle 'rgba(20,16,42,0.35)'; for (sx = x+2+8; sx < x+2+fw; sx += 8) fillRect(sx, y+2, 1, h-4); (5) when opts.ghost (a value in the same units as `value`) gives gf = clamp(ghost/max,0,1) > frac: fillStyle 'rgba(255,255,255,0.35)', fillRect(x+2+fw, y+2, (w-4)*(gf-frac), h-4); (6) lineWidth 2, strokeStyle COLOR.ink, strokeRect(x, y, w, h). Export `drawStatBar(ctx, x, y, w, h, frac, color, iconName)`: drawIcon(ctx, iconName, x, y + Math.round((h-24)/2), 24) (import drawIcon from './icons.js'), then drawBar2(ctx, x+32, y, w-32, h, frac, 1, color).",
   "`tests/anim_bars.test.mjs`: tweenValue(makeTween(0,100,0,1000,'linear'),250) is 25; before start gives 0, after end 100; counter: c=makeCounter(0); counterSet(c,1000,0); counterValue(c,350) is 875 (outCubic(0.5)=0.875 of 1000), counterValue(c,700) is 1000; retarget: counterSet(c,0,350) then counterValue(c,350) is 875 and counterValue(c,1050) is 0; barAnim: a=makeBarAnim(1); barAnimSet(a,0.4,0): values at 450 -> value 0.4 (within 1e-9), at 300 -> ghost 1, at 750 -> ghost 0.4; increasing 0.4 -> 0.9 at t 1000: ghost equals value at t 1200. drawBar2(ctx,10,10,100,20,5,10,'#f00') contains the call fillRect [12,12,48,16]; exactly 5 tick fillRects of width 1 (sx = 20,28,36,44,52); value 0 -> inner fillRect [12,12,0,16] and no ticks and no shine; max 0 -> same as empty; with {ghost:8} an extra fillRect [60,12,28.8,16] (96*(0.8-0.5)) appears with fillStyle 'rgba(255,255,255,0.35)'; strokeStyle COLOR.ink with lineWidth 2 is set last."],
  accept=["`make test 2>&1 | grep 'PASS tests/anim_bars.test.mjs'` prints one line.", NOEDIT],
  oos=["src/ui/kit_draw.js (GU21)."]),

 dict(id="GU08", title="RSAMH speech banner: top zone with tail, dither and typewriter", needs=["GU01", "GU02", "GU05"],
  files=["src/ui/banner.js", "tests/banner.test.mjs"],
  goal="The big rounded speech-banner across the top 120px that carries all narration, Dave's chatter and headlines, as in Rock Star Ate My Hamster: peach-to-tan gradient, ordered-dither shade, thick ink outline, a pointed tail toward the speaker, ALL-CAPS pixel type revealed like a typewriter, paged when long.",
  read=[GUD, TOK, THEME, FK, "src/art/speech.js (the old small speech bubble: this replaces it as the main narration voice)"],
  steps=[
   "`src/ui/banner.js` (imports COLOR, ZONES from tokens; textfit is NOT needed). Export `BANNER_RECT` = {x:16, y:8, w:1248, h:104}, `BANNER_TEXT` = {x:44, y:24, w:1192, lineH:28, perPage:3}. Export `bannerPages(ctx, text)` -> string[][]: uppercase the text, set `ctx.font = '16px \"Press Start 2P\", monospace'`, greedy-wrap to BANNER_TEXT.w (word by word, `measureText`, paragraphs split on newline), then chunk the lines in groups of 3: each group is one page. Export `typewriterChars(total, elapsedMs, cps = 40)` = Math.min(total, Math.floor(elapsedMs * cps / 1000)).",
   "Export `drawBanner(ctx, text, opts)`: opts {tailX: 1040, tailY: 150, page: 0, reveal: 1 (0..1), tailBase: null}. Order: (1) the tail first: tb = tailBase !== null ? tailBase : clamp(tailX, 60, 1220); path moveTo(tb-22, 108), lineTo(tailX, tailY), lineTo(tb+22, 108), closePath; fillStyle COLOR.bannerBottom, fill; lineWidth 5, strokeStyle COLOR.ink, stroke. (2) the body: a rounded-rect path of BANNER_RECT with radius 22 (moveTo/lineTo/quadraticCurveTo like kit_draw's roundRectPath, written privately); gradient `ctx.createLinearGradient(0, 8, 0, 112)` with stops 0 -> COLOR.bannerTop and 1 -> COLOR.bannerBottom as fillStyle; fill; lineWidth 5; strokeStyle COLOR.ink; stroke (this stroke also covers the tail base). (3) ordered dither: fillStyle 'rgba(196,139,85,0.5)' (COLOR.bannerDither at half alpha); for yy = 64; yy < 104; yy += 4: row = (yy-64)/4; start xx = 28 + (row % 2) * 4; for (xx = start; xx <= 1244; xx += 8) fillRect(xx, yy, 2, 2). (4) the text of page `page` (clamped to the last page): lines = bannerPages(ctx, text)[page] (empty array for empty text); total = sum of line lengths; shown = Math.floor(total * clamp(reveal, 0, 1)); draw lines top to bottom at x BANNER_TEXT.x, y BANNER_TEXT.y + i*28, font 16px Press Start 2P, textBaseline 'top', textAlign 'left', fillStyle COLOR.ink, each line sliced to what remains of `shown`; when reveal < 1 also draw '_' (same font) right after the last visible character on its line. Return {pages: <page count, 1 for empty text>, page: <page used>, shown, total}.",
   "`tests/banner.test.mjs`: bannerPages(ctx,'hello') is [['HELLO']]; a text of 7 wrapped lines gives 3 pages with line counts 3,3,1 (build it from 7 words of 60 chars each: 60*0.6*16=576 so two words never share a 1192 line... use 7 words of 80 chars: 768 wide, each on its own line); empty text gives []. drawBanner(ctx,'Hello world',{}) -> texts include 'HELLO WORLD'; exactly 1525 fillRects with fillStyle 'rgba(196,139,85,0.5)' (5 rows of 153 starts at 28 and 5 rows of 152 starts at 32: count them by filtering fillRect calls of size [2,2] that follow that fillStyle); a createLinearGradient call with args [0,8,0,112] whose stops are [[0,'#F6CFA0'],[1,'#D9A66F']]; the last stroke has lineWidth 5 and strokeStyle '#14102A'; the tail path contains lineTo(1040,150); with tailX 2000 the tail base is clamped to 1220 (a moveTo(1198,108)); reveal 0.5 on 'HELLO WORLD' draws 'HELLO' (floor(5.5)) plus a separate '_' text; reveal 1 draws no '_'; a 7-line text with page 1 draws the 4th, 5th and 6th lines and returns pages 3; page 99 clamps to 2; typewriterChars(11,100) is 4 and typewriterChars(11,10000) is 11; every fillRect lies inside [0,1280] x [0,200]."],
  accept=["`make test 2>&1 | grep 'PASS tests/banner.test.mjs'` prints one line.", NOEDIT],
  oos=["src/art/speech.js stays as it is (the office switches to the banner in GU24)."]),

 dict(id="GU09", title="HUD parts: Gold Number Plate icons and the green CASH bar", needs=["GU01", "GU04", "GU07"],
  files=["src/ui/hudparts.js", "tests/hudparts.test.mjs"],
  goal="The two goal pieces of the bottom HUD strip: four gold-disc plate icons (grey until won, with a glint when won) and the green CASH bar with the money figure over it.",
  read=[GUD, TOK, THEME, FK, "src/core/state.js (PLATE_KEYS = ['fatcat','stable','household','hammer'])", "src/core/format.js (`money`)", "src/ui/icons.js (GU04: drawIcon, plate_* names)", "src/ui/bars.js (GU07: drawBar2)"],
  steps=[
   "`src/ui/hudparts.js` imports PLATE_KEYS from '../core/state.js', money from '../core/format.js', drawIcon from './icons.js', drawBar2 from './bars.js', COLOR from './tokens.js', PALETTE from './theme.js'. Export `PLATE_SLOTS` = for i in 0..3: {key: PLATE_KEYS[i], x: 24 + i*64, y: 600, w: 48, h: 48} and `CASH_RECT` = {x:24, y:660, w:260, h:36}. Export `drawPlate(ctx, slot, won, t)`: drawIcon(ctx, 'plate_' + slot.key, slot.x, slot.y, 48, {grey: !won}); when won also draw a glint: gx = slot.x + 8 + Math.floor(((t * 0.5) % 1) * 28); fillStyle '#FFFFFF'; fillRect(gx, slot.y + 10, 2, 8); fillRect(gx - 3, slot.y + 13, 8, 2) (always exactly these two fillRects after the icon, so tests can count them).",
   "Export `drawCashBar(ctx, rect, cash, goal = 100000)`: colour = cash >= 0 ? COLOR.cashGreen : PALETTE.bad; value = cash >= 0 ? cash : Math.min(-cash, 20000); max = cash >= 0 ? goal : 20000; drawBar2(ctx, rect.x, rect.y, rect.w, rect.h, value, max, colour); drawIcon(ctx, 'coin', rect.x + 6, rect.y + 6, 24); then the figure: text = money(cash); font '32px VT323, monospace' (kind body, 32px), textAlign 'center', textBaseline 'middle', cx = rect.x + rect.w/2 + 12, cy = rect.y + rect.h/2 + 1; first draw the text in COLOR.ink at the four offsets (cx-2,cy), (cx+2,cy), (cx,cy-2), (cx,cy+2) (an outline so it is readable on green or dark), then fillStyle '#FFFFFF' at (cx, cy). Return nothing.",
   "`tests/hudparts.test.mjs`: PLATE_SLOTS has 4 entries with keys in PLATE_KEYS order, x 24,88,152,216, y 600, w 48, h 48; drawPlate(ctx, slot, false, 0) uses fillStyle '#B8B8B8' and never '#FFE27A', and makes no '#FFFFFF' fillRect; drawPlate(.., true, 0) uses '#FFE27A' and has exactly two '#FFFFFF' fillRects, the first [32,610,2,8] for slot 0 (gx = 24+8+0); gx moves with t: gx = 24+8+Math.floor(((t*0.5)%1)*28), so t=1 gives 46, t=0.5 gives 39 and t=2 gives 32 again (assert the first glint fillRect x for those t); all fillRects stay inside the 48x48 slot (glint included). drawCashBar(ctx, CASH_RECT, 20000): texts include '£20,000' (exactly 5 fillText calls: four outline + one white), the bar inner fill is [26,662,51.2,32] (256*0.2 = 51.2: assert via the fillRect whose y is 662 and h 32), fillStyle COLOR.cashGreen is used; cash -500 draws money '-£500', uses PALETTE.bad and the inner fill width 256*(500/20000) = 6.4; cash 250000 clamps the fill to the full width 256; a coin icon is drawn (some fillRect with fillStyle '#FFE27A' inside [30,54] x [666,690])."],
  accept=["`make test 2>&1 | grep 'PASS tests/hudparts.test.mjs'` prints one line.", NOEDIT],
  oos=["src/art/hud.js (the old top HUD stays until GU24 stops calling it)."]),

 dict(id="GU10", title="Calendar sheet with tear-off animation", needs=["GU01", "GU05", "GU07"],
  files=["src/ui/calendarsheet.js", "tests/calendarsheet.test.mjs"],
  goal="The torn-off wall-calendar sheet of the RSAMH HUD (weekday, date, big day number) and the animation where the old sheet is ripped off and flutters away revealing the next day.",
  read=[GUD, TOK, THEME, FK, "src/core/clock.js (`dateOf(day)` returns {month, dayOfMonth, monthName})", "src/ui/panels2.js (GU05: chunkyPanel)"],
  steps=[
   "`src/ui/calendarsheet.js` imports dateOf from '../core/clock.js', chunkyPanel from './panels2.js', COLOR/EASE/clamp01 from './tokens.js'. Export `dayParts(day)` -> {weekday, dom, month}: weekday = ['MON','TUE','WED','THU','FRI','SAT','SUN'][(day-1) % 7] (day 1 is a Monday), dom = dateOf(day).dayOfMonth, month = dateOf(day).monthName.slice(0,3).toUpperCase(). Export `drawCalendarSheet(ctx, x, y, w, h, day)`: chunkyPanel(ctx, x, y, w, h, {fill: COLOR.paper, shadow: 0}); header band fillStyle COLOR.enamelRed, fillRect(x+3, y+3, w-6, 28); header text `${weekday} ${dom padded to 2 digits} ${month}` (example 'MON 01 JAN') in '16px \"Press Start 2P\", monospace' white, textAlign center, textBaseline middle at (x+w/2, y+17); big number String(dom) in '48px \"Press Start 2P\", monospace' COLOR.ink, center/middle at (x+w/2, y+61); caption `DAY ${day}/365` in '24px VT323, monospace', fillStyle '#444444', center/middle at (x+w/2, y+h-16). (Layout is for w >= 180 and h >= 114.)",
   "Export `drawCalendarTear(ctx, x, y, w, h, dayFrom, dayTo, p)`: p = clamp01(p). Always draw drawCalendarSheet for dayTo first (the sheet underneath). When p < 1 draw the old sheet on top: e = EASE.outCubic(p); ox = x + w*0.1; oy = y; ctx.save(); ctx.globalAlpha = 1 - e*e; ctx.translate(ox + 60*e, oy - 50*e); ctx.rotate(-0.5*e); ctx.translate(-ox, -oy); drawCalendarSheet(ctx, x, y, w, h, dayFrom); ctx.restore(). When p >= 1 only the underneath sheet is drawn and there is no save/restore at all.",
   "`tests/calendarsheet.test.mjs`: dayParts(1) is {weekday:'MON', dom:1, month:'JAN'}; dayParts(8).weekday is 'MON'; dayParts(32) is {weekday:'THU', dom:1, month:'FEB'} (day 32: (31 % 7)=3 -> THU); drawCalendarSheet(ctx,610,598,180,114,1): texts are exactly ['MON 01 JAN','1','DAY 1/365'] in that order; header text drawn at y 615; caption at y 696; the header band is the fillRect [613,601,174,28] with fillStyle '#B3282D'; no text box leaves [610,790] x [598,712] (use tests/uiaudit.js from GU03 if it is merged, otherwise compute with width = chars*0.6*px) and the three texts do not overlap each other. drawCalendarTear at p 1 draws exactly one sheet (3 texts, zero rotate calls); at p 0.5: two sheets (6 texts), one `rotate` with arg -0.4375 (within 1e-9), (call it as drawCalendarTear(ctx,610,598,180,114,1,2,0.5): ox = 628, oy = 598) one translate [680.5, 554.25] (ox+52.5, oy-43.75) followed by translate [-628, -598], globalAlpha set to 0.234375 (1 - 0.875^2) then restored (`restore` called); the first 3 texts belong to dayTo ('TUE 02 JAN', '2', 'DAY 2/365') and the next 3 to dayFrom ('MON 01 JAN', '1', 'DAY 1/365')."],
  accept=["`make test 2>&1 | grep 'PASS tests/calendarsheet.test.mjs'` prints one line.", NOEDIT],
  oos=["src/art/calendar.js (the big wall calendar prop stays)."]),

 dict(id="GU11", title="Bottom HUD strip: plates, cash bar, car portrait, calendar, chart panel", needs=["GU03", "GU04", "GU05", "GU07", "GU09", "GU10"],
  files=["src/ui/hudstrip.js", "tests/hudstrip.test.mjs"],
  goal="The permanent bottom HUD strip (zone y 590..720) assembled from the parts: four plate icons and the CASH bar on the left, the selected-car portrait slot, the calendar sheet, and a small white chart panel with reputation, buzz and year-progress bars.",
  read=[GUD, TOK, THEME, FK, "src/ui/hudparts.js (GU09)", "src/ui/calendarsheet.js (GU10)", "src/ui/bars.js (GU07)", "src/art/hud.js (the old top HUD: for the state field names `cash`, `reputation`, `buzz`, `day`, `plates`)"],
  steps=[
   "`src/ui/hudstrip.js`. Export `HUD_RECTS` = {plates: PLATE_SLOTS (from hudparts), cash: CASH_RECT, portrait: {x:320,y:598,w:260,h:114}, calendar: {x:610,y:598,w:180,h:114}, chart: {x:820,y:598,w:440,h:114}}. Export `drawHudStrip(ctx, state, view, t)`; view = {cashShown (number, default state.cash), portrait (function(ctx, rect) or null), nowMs (0), dayChangedAt (undefined), prevDay (undefined)}. Order: (1) background fillStyle COLOR.hudBg fillRect(0, 590, 1280, 130); fillStyle COLOR.brass fillRect(0, 590, 1280, 4); fillStyle COLOR.brassDark fillRect(0, 594, 1280, 2). (2) the four plates: drawPlate(ctx, slot, state.plates && state.plates[slot.key] === true, t). (3) drawCashBar(ctx, CASH_RECT, view.cashShown !== undefined ? view.cashShown : state.cash). (4) portrait: c = chunkyPanel(ctx, p.x, p.y, p.w, p.h, {fill: COLOR.enamelNavy, shadow: 0}); then view.portrait ? view.portrait(ctx, c) : text 'NO CAR' in '28px VT323, monospace', fillStyle '#959595', center/middle at the centre of c. (5) calendar: day = state.day; when view.dayChangedAt is a number: p = clamp01((view.nowMs - view.dayChangedAt)/700), prev = view.prevDay !== undefined ? view.prevDay : Math.max(1, day-1); drawCalendarTear(ctx, cal.x, cal.y, cal.w, cal.h, prev, day, p); otherwise drawCalendarSheet. (6) chart panel: c = chunkyPanel(ctx, ch.x, ch.y, ch.w, ch.h, {fill: COLOR.chartWhite, shadow: 0}); three rows i=0..2 at row y = ch.y + 10 + i*30: icon (star, buzz, calendar) via drawIcon(ctx, name, ch.x+14, rowY-1, 24); drawBar2(ctx, ch.x+48, rowY, 280, 22, value, 100 (365 for the third), colour) with values state.reputation, state.buzz, state.day and colours PALETTE.good, COLOR.warn, COLOR.info; value text in '24px VT323, monospace', fillStyle COLOR.ink, textAlign 'right', baseline 'middle' at (ch.x+ch.w-14, rowY+11): String(Math.round(rep)), String(Math.round(buzz)), `${day}/365`.",
   "`tests/hudstrip.test.mjs` with `startGame(3)` from src/sim/newgame.js as the state (cash 20000, reputation 40, buzz 0, day 1): drawHudStrip(ctx,state,{},0) texts include '£20,000', 'DAY 1/365', 'MON 01 JAN', 'NO CAR', '40', '0', '1/365'; the first fillRect is [0,590,1280,130] with fillStyle '#1B1735'; every fillRect, arc and text box lies inside [0,1280] x [590,720] (strokeRect and arc too; use tests/uiaudit.js from GU03 for text boxes: auditCtx(ctx) must give belowFloor.length 0, offCanvas.length 0 and overlaps.length 0); a portrait callback is called exactly once with a rect {x:327,y:605,w:246,h:100} (chunkyPanel content: 320+3+4, 598+3+4, 260-14, 114-14) and 'NO CAR' is then not drawn; with state.plates.fatcat = true the draw uses '#FFE27A' and without any won plate it does not; with state.day set to 2, dayChangedAt 1000 and nowMs 1350 (p 0.5) two calendar sheets are drawn (texts 'DAY 2/365' then 'DAY 1/365'); with dayChangedAt unset exactly one sheet; the HUD_RECTS rects do not overlap each other (cash vs plates: plate bottoms 648 < cash top 660) and all sit inside the hud zone."],
  accept=["`make test 2>&1 | grep 'PASS tests/hudstrip.test.mjs'` prints one line.", NOEDIT],
  oos=["src/art/hud.js and src/ui/scenes/office.js (GU24 switches the office over)."]),

 dict(id="GU12", title="Small in-scene pop-up menu with arrow cursor", needs=["GU01", "GU03", "GU05"],
  files=["src/ui/popmenu.js", "tests/popmenu.test.mjs"],
  goal="RSAMH's small boxed list (FORWARD / REWIND / SELECT) with a bobbing pixel arrow cursor, replacing full-screen menus for quick choices: pure model (selection, keys, hit rows) plus the draw.",
  read=[GUD, TOK, THEME, FK, "src/ui/kit_hits.js (`makeHits().add(id,x,y,w,h,onTap,{enabled})`)", "docs/SCENE_RULES.md (TAP RULE)"],
  steps=[
   "`src/ui/popmenu.js` (imports paperPanel from './panels2.js', COLOR from './tokens.js', PALETTE from './theme.js'). Export `makePopMenu(items, opts)`: items = [{id, label, enabled=true}], opts {x:0, y:0, w:240}; returns {items, x, y, w, h: 24 + 44*items.length, sel: first enabled index (0 when none)}. Export `popRowRect(m, i)` = {x: m.x+12, y: m.y+12+44*i, w: m.w-24, h: 44}. Export `popAt(m, px, py)` -> row index under the point or -1 (rows only, enabled or not). Export `popMove(m, dir)`: dir +1 or -1; step through the rows with wrap-around until an enabled row is found; if there is none leave sel unchanged. Export `popKey(m, key)`: 'ArrowDown' or 's' -> popMove(+1) and return 'move'; 'ArrowUp' or 'w' -> popMove(-1), 'move'; 'Enter' or ' ' -> return 'pick' (only when the selected row is enabled, else null); anything else null. Export `popAddHits(m, hits, onPick)`: for each row hits.add('pop:' + item.id, rect.x, rect.y, rect.w, rect.h, function () { onPick(item.id); }, {enabled: item.enabled !== false}).",
   "Export `drawPopMenu(ctx, m, t)`: paperPanel(ctx, m.x, m.y, m.w, m.h); for each row i: r = popRowRect; when i === m.sel and the item is enabled: fillStyle 'rgba(255,210,122,0.55)', fillRect(r.x, r.y, r.w, r.h); text = item.label uppercased, font '16px \"Press Start 2P\", monospace', textAlign 'left', textBaseline 'middle', fillStyle (enabled ? COLOR.ink : PALETTE.midgrey), fillText(text, r.x + 40, r.y + 22). The cursor on the selected row: bitmap rows (8x8) ['...o....','...oo...','oooooo..','ooooooo.','ooooooo.','oooooo..','...oo...','...o....'] (32 'o' cells); off = (Math.floor(t*4) % 2) * 4; for each 'o' cell (cx, cy) fillStyle COLOR.ink, fillRect(r.x + 4 + off + cx*3, r.y + 10 + cy*3, 3, 3) (one fillRect per cell: exactly 32).",
   "`tests/popmenu.test.mjs`: m = makePopMenu([{id:'fwd',label:'Forward'},{id:'rew',label:'Rewind'},{id:'sel',label:'Select',enabled:false}],{x:100,y:200,w:240}); m.h is 156; popRowRect(m,1) is {x:112,y:256,w:216,h:44}; popAt(m,120,260) is 1, popAt(m,99,260) is -1, popAt(m,120,10) is -1; m.sel starts 0; popMove(m,1) -> 1; popMove(m,1) -> 0 (row 2 disabled is skipped, wraps); popMove(m,-1) -> 1; popKey: 'ArrowDown' returns 'move', 'Enter' returns 'pick' on an enabled row and null when sel is the disabled row (set m.sel = 2 by hand), 'x' returns null. All-disabled menu: sel 0 and popMove leaves it 0. popAddHits makes 3 hits with ids 'pop:fwd','pop:rew','pop:sel', and `hits.tap(120, 220)` calls onPick('fwd') while tapping the disabled row calls nothing. drawPopMenu: texts are ['FORWARD','REWIND','SELECT']; exactly 32 cursor fillRects of size [3,3] with fillStyle '#14102A'; at t 0 the first cursor cell x is 112+4+9=125... compute from the formula (r.x+4+off+cx*3 with cx 3 for the first cell of row 0): [r.x+4+0+9, r.y+10, 3, 3] = [125, 222, 3, 3]; at t 0.25 (off 4) it is [129,222,3,3]; the disabled row's text colour is '#6C6C6C'; auditCtx from tests/uiaudit.js (GU03) reports no belowFloor, no overlaps."],
  accept=["`make test 2>&1 | grep 'PASS tests/popmenu.test.mjs'` prints one line.", NOEDIT],
  oos=["Any scene (wave 2 converts scenes to pop-ups)."]),

 dict(id="GU13", title="Particles: confetti, smoke, sparks, cash, rust flakes", needs=["GU01"],
  files=["src/ui/particles.js", "tests/particles.test.mjs"],
  goal="A deterministic particle engine with five kinds from a data table, for endgame confetti, exhaust smoke, breakdown sparks, cash showers on sales and rust flakes on faults.",
  read=[GUD, TOK, FK, "src/art/common.js (`smokePuff`, for the existing smoke look)"],
  steps=[
   "`src/ui/particles.js`. " + PURE + " Private seeded generator: `next(ps)` = mulberry32-style on ps.seed using Math.imul (`ps.seed = (ps.seed + 0x6D2B79F5) | 0; let z = Math.imul(ps.seed ^ (ps.seed >>> 15), 1 | ps.seed); z = (z + Math.imul(z ^ (z >>> 7), 61 | z)) ^ z; return ((z ^ (z >>> 14)) >>> 0) / 4294967296`) and `rr(ps, lo, hi)` = lo + (hi-lo)*next(ps). Export `makeParticles(seed = 1)` -> {seed, list: []} and `liveCount(ps)` = ps.list.length. Export const `MAX_PARTICLES` = 300. Export `KINDS`: confetti {colors:['#E8B923','#D9483B','#3FAE49','#70A4B2','#6F3D86','#FFFFFF'], life:[1800,2600], vx:[-160,160], vy:[-420,-180], g:420}; smoke {life:[1200,1900], vx:[-14,14], vy:[-70,-30], g:-6, r0:6, r1:22}; sparks {colors:['#FFD27A','#FFFFFF'], life:[300,550], speed:[200,420], g:600}; cash {life:[1100,1600], vx:[-90,90], vy:[-380,-220], g:700}; rust {colors:['#8A4B26','#5A2E14'], life:[900,1400], vx:[-50,50], vy:[-80,0], g:500}.",
   "Export `emit(ps, kind, x, y, n)`: for each of n: stop silently when liveCount >= MAX_PARTICLES; draw random numbers IN THIS ORDER: life, then (sparks: angle = rr(0, 2*PI) and speed, vx = cos*speed, vy = sin*speed; others: vx then vy), then colour index (kinds with colors; floor(next*len)), then a phase = rr(0, 6.28); push {kind, x, y, vx, vy, age:0, life, color, phase}. Export `updateParticles(ps, dtMs)`: for every particle age += dtMs; vy += g*dtMs/1000; x += vx*dtMs/1000; y += vy*dtMs/1000; then remove those with age >= life (stable order). Export `drawParticles(ctx, ps)`: u = age/life. confetti: w = 2 + 4*Math.abs(Math.cos(age*0.02 + phase)); fillStyle color; fillRect(x, y, w, 6) (one fillRect). smoke: radius = r0 + (r1-r0)*u; fillStyle `rgba(200,200,210,${(0.5*(1-u)).toFixed(3)})`; beginPath, arc(x, y, radius, 0, 2*PI), fill (one arc + one fill). sparks: fillStyle color; fillRect(x, y, 3, 3). cash: fillStyle '#14102A', fillRect(x-4, y-4, 8, 8); fillStyle '#E8B923', fillRect(x-3, y-3, 6, 6) (two fillRects). rust: fillStyle color; fillRect(x, y, 4, 4). Alpha for confetti/sparks/cash/rust: when u > 0.8 wrap that particle in save, globalAlpha = (1-u)/0.2, restore.",
   "`tests/particles.test.mjs`: makeParticles(1) -> liveCount 0; emit confetti n=10 -> 10; updateParticles(ps, 3000) -> 0; two engines with the same seed and the same emit calls have JSON-identical `list` (also after updateParticles(ps, 100)); different seeds differ; emit n=500 sparks gives exactly 300 (MAX_PARTICLES); every confetti colour is one of the 6 listed; sparks speed: hypot(vx,vy) between 200 and 420 (within 1e-6); after emit of 1 cash at (100,100) and updateParticles(ps,100) x moves by vx*0.1 and vy changed by +70 (g 700*0.1) before moving; drawParticles for 10 confetti makes exactly 10 fillRects of height 6 and width between 2 and 6; 4 cash particles make 8 fillRects (4 of size [8,8]); 3 smoke make 3 arcs; a particle with age/life 0.9 draws inside save/restore with globalAlpha 0.5 (within 1e-9)."],
  accept=["`make test 2>&1 | grep 'PASS tests/particles.test.mjs'` prints one line.", "`grep -nE 'Math.random|Date' src/ui/particles.js` prints nothing.", NOEDIT],
  oos=["Wiring into the app (GU22)."]),

 dict(id="GU14", title="Screen shake, flashes and the disaster / good-news presets", needs=["GU01"],
  files=["src/ui/screenfx.js", "tests/screenfx.test.mjs"],
  goal="Deterministic screen shake and colour flashes, called by breakdowns (red flash and shake), sales and plates (gold flash), and a short hit-stop. Time comes in as nowMs.",
  read=[GUD, TOK, FK],
  steps=[
   "`src/ui/screenfx.js` (imports MOTION from tokens). " + PURE + " Export `makeScreenFx()` -> {shake: null, flash: null, freezeUntil: 0}. `fxShake(fx, mag, ms, nowMs)` sets fx.shake = {mag, ms, start: nowMs} (a stronger new shake replaces a weaker running one: keep the old when its remaining amplitude is bigger). `fxFlash(fx, color, ms, nowMs, peak = 0.8)` sets fx.flash = {color, ms, start: nowMs, peak}. `fxFreeze(fx, ms, nowMs)` sets freezeUntil = nowMs + ms; `fxFrozen(fx, nowMs)` = nowMs < fx.freezeUntil. `fxActive(fx, nowMs)` is true while a shake or flash is still running. Presets: `fxDisaster(fx, nowMs)` = shake 14 for 500ms + flash '#D9483B' 260ms peak 0.6 + freeze 80ms; `fxGood(fx, nowMs)` = flash '#FFD27A' 200ms peak 0.35 (no shake); `fxBump(fx, nowMs)` = shake 4 for 150ms.",
   "`shakeOffset(fx, nowMs)` -> {dx, dy}: no shake or age >= ms gives {dx:0, dy:0}; else age = nowMs - start; amp = mag*(1 - age/ms); dx = Math.round(amp*Math.sin(age*0.09)); dy = Math.round(amp*Math.cos(age*0.13)). `flashAlpha(fx, nowMs)`: no flash or age >= ms gives 0; else u = age/ms; peak*(1-u)*(1-u). `fxBegin(ctx, fx, nowMs)`: ctx.save(); o = shakeOffset; when dx or dy is non-zero ctx.translate(dx, dy). `fxEnd(ctx, fx, nowMs)`: ctx.restore(); a = flashAlpha; when a > 0.001: fillStyle rgba of the flash colour (use rgba() from './theme.js') with alpha a, fillRect(0, 0, 1280, 720); expired shake/flash are set back to null here.",
   "`tests/screenfx.test.mjs`: shake mag 10 ms 300 start 0: shakeOffset at 0 is {dx:0,dy:10}; at 100 is {dx:3,dy:6} (amp 6.667; round(6.667*sin 9)=3, round(6.667*cos 13)=6); at 300 and after is {dx:0,dy:0}; a weaker second shake (mag 2) while a mag-10 shake is fresh does not replace it; flash peak 0.8 ms 180: alpha at 0 is 0.8, at 90 is 0.2 (within 1e-9), at 180 is 0; fxBegin makes one `save` and, when the offset is non-zero, a translate with the offset; fxEnd makes one `restore` and a fillRect [0,0,1280,720] whose fillStyle is 'rgba(217,72,59,0.xxx)' for the disaster preset at age 0 (alpha 0.6: assert the fillStyle starts with 'rgba(217,72,59,0.6'); after the flash expired fxEnd draws no fillRect and sets fx.flash to null; fxDisaster sets freezeUntil to nowMs+80 and fxFrozen is true at +79, false at +80; fxGood has no shake (fx.shake null); fxActive false on a fresh fx."],
  accept=["`make test 2>&1 | grep 'PASS tests/screenfx.test.mjs'` prints one line.", NOEDIT],
  oos=["Wiring into the app (GU22)."]),

 dict(id="GU15", title="Screen transitions A: fade, slide, iris", needs=["GU01"],
  files=["src/ui/transitions.js", "tests/transitions.test.mjs"],
  goal="A transition runner that draws an outgoing and an incoming screen through callbacks (no offscreen canvas needed): cross-fade, slide in four directions, and the iris close-and-open.",
  read=[GUD, TOK, FK],
  steps=[
   "`src/ui/transitions.js` (imports EASE, MOTION, clamp01 from tokens). Export `makeTransition(kind, nowMs, durMs)`: kind is 'fade', 'slide-left', 'slide-right', 'slide-up', 'slide-down', 'iris' (the card GU16 adds 'static' and 'pageturn'; an unknown kind throws Error('bad transition')); default durMs from MOTION: fade -> fade, slide-* -> slide, iris -> iris. Returns {kind, start: nowMs, dur}. `transProgress(tr, nowMs)` = clamp01((nowMs - tr.start)/tr.dur); `transDone(tr, nowMs)` = nowMs >= tr.start + tr.dur.",
   "Export `drawTransition(ctx, tr, nowMs, drawFrom, drawTo, w = 1280, h = 720)`; u = transProgress. fade: e = EASE.inOutQuad(u); drawFrom(); save; globalAlpha = e; drawTo(); restore. slide-*: e = EASE.outCubic(u); this exact table (old screen first, then new screen): left: old translate(-e*w, 0), new translate((1-e)*w, 0); right: old translate(e*w, 0), new translate(-(1-e)*w, 0); up: old translate(0, -e*h), new translate(0, (1-e)*h); down: old translate(0, e*h), new translate(0, -(1-e)*h). Each draw is wrapped in save/restore and a clip: beginPath, rect(0,0,w,h), clip, inside the save. iris: fillStyle '#000000', fillRect(0,0,w,h); R = Math.hypot(w/2, h/2); when u < 0.5: r = R*(1 - 2u), scene = drawFrom, else r = R*(2u - 1), scene = drawTo; save; beginPath; arc(w/2, h/2, r, 0, Math.PI*2); clip; scene(); restore (only ONE scene is drawn per frame). u >= 1 draws only drawTo() without any transform for every kind.",
   "`tests/transitions.test.mjs`: makeTransition('fade',1000) is {kind:'fade',start:1000,dur:250}; 'slide-left' dur 350; 'iris' dur 500; makeTransition('wipe',0) throws; transProgress at start+125 of a fade is 0.5; transDone true at start+dur. Count callbacks with counters: fade at u 0.5 calls both once and sets globalAlpha 0.5 (inOutQuad(0.5)) between a save and restore; slide-left at u 0.5 (e 0.875): translate calls [-1120,0] then [160,0]; slide-right: [1120,0] then [-160,0]; slide-up at u 0.5: [0,-630] then [0,90]; each slide draw has a `clip` call; iris at u 0.25 calls only drawFrom, with arc radius 734.3023900274328*0.5 within 1e-6 at (640,360); iris at u 0.75 calls only drawTo with the same radius; iris at u 0 has radius R and at u 0.5 radius 0; any kind at u >= 1 calls only drawTo with zero translate calls."],
  accept=["`make test 2>&1 | grep 'PASS tests/transitions.test.mjs'` prints one line.", NOEDIT],
  oos=["Wiring into the app (GU22); static and page-turn (GU16)."]),

 dict(id="GU16", title="Screen transitions B: TV-static wipe and newspaper page-turn", needs=["GU15"],
  files=["src/ui/transitions2.js", "tests/transitions2.test.mjs"],
  goal="Two more transitions: the TV-static wipe (for the Webb TV shop) and the page-turn (for the newspaper), as pure draw functions with the same (ctx, tr, nowMs, drawFrom, drawTo) signature as GU15.",
  read=[GUD, TOK, FK, "src/ui/transitions.js (GU15: makeTransition, transProgress)"],
  steps=[
   "`src/ui/transitions2.js` imports transProgress from './transitions.js' and EASE from './tokens.js'. Export `staticCells(cols, rows, coverage, frame)` -> array of {i, j, level}: for j in 0..rows-1 and i in 0..cols-1 compute hash h = (Math.imul(i + 1, 73856093) ^ Math.imul(j + 1, 19349663) ^ Math.imul(frame + 1, 83492791)) >>> 0; the cell is included when (h % 1000)/1000 < coverage; level = (h >>> 10) % 4. Export `STATIC_COLORS` = ['#101010','#505050','#A0A0A0','#F0F0F0'].",
   "Export `drawStaticWipe(ctx, tr, nowMs, drawFrom, drawTo, w = 1280, h = 720)`: u = transProgress; u >= 1 -> drawTo() only. Else draw the scene (drawFrom when u < 0.5, else drawTo), then the static: coverage = 1 - Math.abs(2*u - 1) (0 at the ends, 1 in the middle), frame = Math.floor(nowMs/50); cells = staticCells(40, 23, coverage, frame) (32px cells: 1280/32 = 40 columns, 720/32 = 22.5 -> 23 rows); for each cell fillStyle STATIC_COLORS[level], fillRect(i*32, j*32, 32, 32). Export `drawPageTurn(ctx, tr, nowMs, drawFrom, drawTo, w = 1280, h = 720)`: u >= 1 -> drawTo() only. Else drawTo() first (underneath); e = EASE.inOutQuad(u); sx = 1 - e; save; beginPath; rect(0, 0, w, h); clip; scale(sx, 1); drawFrom(); restore (the old page squashes toward the left spine); then the page-edge shadow: edgeX = sx*w; fillStyle `rgba(0,0,0,${(0.3*(1-u)).toFixed(3)})`, fillRect(edgeX, 0, 24, h); and a light edge fillStyle 'rgba(255,247,220,0.8)', fillRect(edgeX - 3, 0, 3, h).",
   "`tests/transitions2.test.mjs`: staticCells(40,23,0,5) is empty; staticCells(40,23,1,5) has all 920 cells (every (h % 1000)/1000 < 1) and every level is 0..3; same arguments twice give identical arrays; coverage 0.5 gives between 400 and 520 cells (statistical: 920*0.5=460); a different frame gives a different cell list. drawStaticWipe at u 0.5 (tr = {kind:'static', start:0, dur:400}, nowMs 200): drawFrom is NOT called (u < 0.5 is false at exactly 0.5, so drawTo is called), exactly 920 fillRects of size [32,32] with colours in STATIC_COLORS; at u 0.25: drawFrom called once, drawTo not, and the number of 32x32 fillRects is between 380 and 540 (coverage 0.5); at u 0 no static fillRect at all; u >= 1 only drawTo. drawPageTurn at u 0.5 (e 0.5, sx 0.5): drawTo then drawFrom each once, exactly one scale call [0.5, 1], the shadow fillRect [640, 0, 24, 720] with fillStyle 'rgba(0,0,0,0.150)', the light edge fillRect [637,0,3,720]; at u 0.1 sx = 1 - inOutQuad(0.1) = 1 - 0.02 = 0.98 (assert the scale arg within 1e-9); u >= 1 only drawTo with no scale call."],
  accept=["`make test 2>&1 | grep 'PASS tests/transitions2.test.mjs'` prints one line.", NOEDIT],
  oos=["Wiring into the app (GU22) and the news scene."]),

 dict(id="GU17", title="CRT overlay and shared TV-static drawing", needs=["GU01"],
  files=["src/ui/crt.js", "tests/crt.test.mjs"],
  goal="The CRT filter the Settings toggle promises (it exists only as a setting today): scanlines in ONE path, a vignette, a slow rolling brightness bar; plus one shared `drawStatic` for TV screens.",
  read=[GUD, FK, "src/art/props.js (`drawTvStatic`, the office TV; it stays as it is)", "src/ui/scenes/settings.js (the CRT toggle writes app.settings.crt)"],
  steps=[
   "`src/ui/crt.js`. " + PURE + " Export `drawCrt(ctx, w, h, t, opts)`: opts {scan: 0.10, vignette: 0.45, sweep: true}. (1) scanlines: ctx.beginPath(); for (y = 0; y < h; y += 3) { moveTo(0, y+1); lineTo(w, y+1); } lineWidth 1; strokeStyle `rgba(0,0,0,${scan})`; ONE stroke call (for h 720 exactly 240 moveTo and 240 lineTo). (2) vignette: g = ctx.createRadialGradient(w/2, h/2, h*0.35, w/2, h/2, w*0.75); g.addColorStop(0, 'rgba(0,0,0,0)'); g.addColorStop(1, `rgba(0,0,0,${vignette})`); fillStyle g; fillRect(0, 0, w, h). (3) when sweep: yy = ((t*0.12) % 1)*(h+80) - 80; g2 = createLinearGradient(0, yy, 0, yy+80) with stops 0 'rgba(255,255,255,0)', 0.5 'rgba(255,255,255,0.04)', 1 'rgba(255,255,255,0)'; fillStyle g2; fillRect(0, yy, w, 80).",
   "Export `staticLevel(i, j, frame, seed)` = ((Math.imul(i + 1, 73856093) ^ Math.imul(j + 1, 19349663) ^ Math.imul(frame + 1, 83492791) ^ Math.imul(seed + 1, 2654435761)) >>> 10) % 4. Export `STATIC_GREYS` = ['#101010','#505050','#A0A0A0','#F0F0F0']. Export `drawStatic(ctx, x, y, w, h, t, opts)`: opts {cell: 8, seed: 1, fps: 20}; frame = Math.floor(t*fps); cols = Math.ceil(w/cell), rows = Math.ceil(h/cell); for each cell fillStyle STATIC_GREYS[staticLevel(i,j,frame,seed)], fillRect(x + i*cell, y + j*cell, Math.min(cell, w - i*cell), Math.min(cell, h - j*cell)) (cells at the edge are cut so nothing leaves the rectangle). Return cols*rows.",
   "`tests/crt.test.mjs`: drawCrt(ctx,1280,720,0) -> exactly 240 `moveTo` and 240 `lineTo`, exactly one `stroke`, strokeStyle 'rgba(0,0,0,0.1)'; createRadialGradient args [640,360,252,640,360,960] with stops [[0,'rgba(0,0,0,0)'],[1,'rgba(0,0,0,0.45)']]; exactly two fillRects: the vignette [0,0,1280,720] and the sweep [0,yy,1280,80] with yy = -80 at t=0; at t=1/0.12 (a full cycle) yy is again -80 within 1e-6; with {sweep:false} only 1 fillRect; with {scan:0.2} strokeStyle 'rgba(0,0,0,0.2)'. staticLevel returns 0..3 for 1000 cells and all four values occur; same arguments same value; a different frame changes at least 50 of 100 cells. drawStatic(ctx,10,20,278,206,0,{cell:8}) returns 35*26 = 910, makes 910 fillRects, the last cell is cut: width 278-34*8 = 6 and height 206-25*8 = 6; no fillRect leaves [10,288] x [20,226]; at t = 0.04 (frame 0) and t = 0.06 (frame 1) the fillStyle sequences differ."],
  accept=["`make test 2>&1 | grep 'PASS tests/crt.test.mjs'` prints one line.", NOEDIT],
  oos=["src/art/props.js, settings.js (wiring is GU23)."]),

 dict(id="GU18", title="Toast v2 (icon, slide-in, fade-out) and tooltips", needs=["GU01", "GU04"],
  files=["src/ui/overlays.js", "tests/overlays.test.mjs"],
  goal="The two small overlays: the toast (kind icon, slide in with a little overshoot, fade out) as pose maths + a draw that sits where the old toast did, and the tooltip (appears after a hover delay, clamped to the screen, arrow toward the target).",
  read=[GUD, TOK, THEME, FK, "src/ui/scenes.js (the existing toast: {text, until}, panel 560x36 at x 360, y 640 - slot*44, text size 28 centred)", "src/ui/icons.js (GU04: tick, cross, warning, paper)"],
  steps=[
   "`src/ui/overlays.js` (imports EASE, MOTION, clamp01 from tokens; drawIcon from './icons.js'; PALETTE from './theme.js'; it must NOT import kit_draw.js, and instead of panel() it receives the panel drawer as a parameter). Export `toastPose(toast, nowMs)`: toast = {born, until}; age = nowMs - born; remaining = until - nowMs; dy = age < MOTION.toast ? 40*(1 - EASE.outBack(clamp01(age/MOTION.toast))) : 0; alpha = Math.min(1, age/130); when remaining < MOTION.toastOut alpha = Math.min(alpha, clamp01(remaining/MOTION.toastOut)); return {dy, alpha}. Export `toastIcon(kind)`: 'good' -> 'tick', 'bad' -> 'cross', 'warn' -> 'warning', 'info' -> 'paper', anything else (including undefined) -> null.",
   "Export `drawToast2(ctx, toast, nowMs, slot, panelFn)`: pose = toastPose; y = 640 - slot*44 + pose.dy; save; globalAlpha = pose.alpha; panelFn(ctx, 360, y, 560, 36) (the caller passes kit_draw's `panel`); icon = toastIcon(toast.kind): when icon draw drawIcon(ctx, icon, 372, y + 6, 24); text: font '28px VT323, monospace', textBaseline 'top', textAlign 'center', fillStyle PALETTE.ink, fillText(toast.text, 640 + (icon ? 16 : 0), y + 4); restore. Export tooltip model `makeTooltip()` -> {id:null, since:0}; `ttHover(tt, id, nowMs)`: when id !== tt.id set tt.id = id and tt.since = nowMs; `ttVisible(tt, nowMs, delay = 400)` = tt.id !== null && nowMs - tt.since >= delay. Export `tooltipRect(textW, ax, ay, bounds)`: bounds default {x:8,y:8,w:1264,h:704}; w = textW + 20; h = 40; x = clamp(ax - w/2, bounds.x, bounds.x + bounds.w - w); y = ay - h - 12; below = y < bounds.y; when below y = ay + 12; return {x, y, w, h, below}. Export `drawTooltip(ctx, text, ax, ay, bounds)`: font '24px VT323, monospace'; r = tooltipRect(ctx.measureText(text).width, ax, ay, bounds); fillStyle '#14102A' fillRect(r.x, r.y, r.w, r.h); fillStyle '#FFF7DC' fillRect(r.x+2, r.y+2, r.w-4, r.h-4); arrow: a triangle path pointing at (ax, ay) from the box edge (above: base on the bottom edge at ax-6..ax+6 clamped inside the box, below: top edge), fill '#14102A'; text fillStyle '#14102A', textBaseline 'middle', textAlign 'center' at (r.x + r.w/2, r.y + r.h/2).",
   "`tests/overlays.test.mjs`: toastPose({born:0,until:2500}, 0) is {dy:40, alpha:0}; at 130 alpha is 1 (age/130); at 260 dy is 0 (outBack(1)=1) and at 130 dy is 40*(1-outBack(0.5)) = 40*(1-1.0876975) = -3.5079 within 1e-4 (a small overshoot above the rest line); at until-100 alpha is 0.5; at until alpha 0; toastIcon('good') 'tick', 'bad' 'cross', 'warn' 'warning', 'info' 'paper', undefined null. drawToast2 at a settled time (nowMs 1000) with a fake panelFn that records its arguments: called once with (ctx,360,640,560,36); slot 2 gives y 552; a kind 'good' toast draws tick icon fillRects inside [372,396] x [646,670] and the text is at x 656; no kind -> text at x 640 and no icon fillRects; texts equal [toast.text]; globalAlpha set to 1 and the call sequence has save ... restore. Tooltip: ttHover(tt,'a',100); ttVisible(tt,499) false, (tt,500) true; ttHover(tt,'b',600) resets: ttVisible(tt,700) false; ttHover(tt,'b',900) does not reset. tooltipRect(100, 640, 300) -> {x:580,y:248,w:120,h:40,below:false}; tooltipRect(100, 10, 300) clamps x to 8; tooltipRect(100, 640, 30) is below: y 42, below true; an off-right case ax 1275 clamps x to 8+1264-120 = 1152. drawTooltip draws the text once and its box fillRects lie inside the bounds."],
  accept=["`make test 2>&1 | grep 'PASS tests/overlays.test.mjs'` prints one line.", NOEDIT],
  oos=["src/ui/scenes.js (GU23)."]),

 dict(id="GU19", title="Day-change sequence: timeline, events and overlay", needs=["GU01", "GU07", "GU08", "GU10"],
  files=["src/ui/daychange.js", "tests/daychange.test.mjs"],
  goal="The ceremony when a day passes (2.4 s): the screen dims, the calendar sheet is torn off, the money delta counts up with coins or rust, and the banner types the headline. A pure timeline, a list of one-shot events (sounds and particle bursts for the app to fire), and the overlay draw.",
  read=[GUD, TOK, FK, "src/ui/calendarsheet.js (GU10: drawCalendarTear)", "src/ui/banner.js (GU08: drawBanner)", "src/core/format.js (money)"],
  steps=[
   "`src/ui/daychange.js` (imports EASE, clamp01, MOTION from tokens; drawCalendarTear; drawBanner; money). " + PURE + " Export `PHASES` = [{id:'dim',t0:0,t1:300},{id:'tear',t0:300,t1:1000},{id:'money',t0:700,t1:1700},{id:'banner',t0:1000,t1:2400},{id:'out',t0:2100,t1:2400}] and `TOTAL` = 2400. Export `dayTimeline(prev, next)`: prev and next are {day, cash, rep, buzz}; returns {prev, next, total: 2400, delta: {cash: next.cash - prev.cash, rep: next.rep - prev.rep, buzz: next.buzz - prev.buzz}}. Export `phaseProgress(tl, ms, id)` -> 0 before t0, 1 after t1, else (ms - t0)/(t1 - t0). Export `dimAlpha(ms)`: 0.55*phaseProgress(dim) while ms < 2100, else 0.55*(1 - phaseProgress(out)); 0 at ms >= 2400.",
   "Export `dayEvents(tl, fromMs, toMs)`: all events with fromMs < at <= toMs, in time order, from this fixed table: {at:300, kind:'sound', name:'paper'}; at 700: when delta.cash > 0 {kind:'sound', name:'coins'} and {kind:'emit', what:'cash', n: Math.min(30, Math.max(6, Math.floor(delta.cash/200)))}; when delta.cash < 0 {kind:'sound', name:'thud'} and {kind:'emit', what:'rust', n: Math.min(30, Math.max(6, Math.floor(-delta.cash/200)))}; when delta.cash is 0 neither; at 1000 {kind:'sound', name:'stamp'}. Export `drawDayChange(ctx, tl, ms, headline)`: when ms <= 0 or ms >= TOTAL do nothing; a = dimAlpha(ms); fillStyle `rgba(20,16,42,${a.toFixed(3)})`, fillRect(0, 0, 1280, 720) (always); drawCalendarTear(ctx, 500, 150, 280, 200, tl.prev.day, tl.next.day, phaseProgress(tl, ms, 'tear')); money text (only when delta.cash != 0): shown = Math.round(delta.cash * EASE.outCubic(phaseProgress(tl, ms, 'money'))); text = (shown >= 0 ? '+' : '') + money(shown) (money() already gives '-£400' for negatives); font '32px \"Press Start 2P\", monospace', textAlign 'center', textBaseline 'middle', fillStyle (delta.cash > 0 ? '#3FAE49' : '#D9483B'), fillText at (640, 400). Headline: when ms >= 1000 and headline: drawBanner(ctx, headline, {reveal: phaseProgress(tl, ms, 'banner')*1.6 (so it finishes typing before the end; clamp done by drawBanner), tailX: 640, tailY: 150}).",
   "`tests/daychange.test.mjs`: tl = dayTimeline({day:1,cash:1000,rep:40,buzz:0},{day:2,cash:2400,rep:41,buzz:3}) has delta {cash:1400,rep:1,buzz:3} and total 2400; phaseProgress(tl,150,'dim') 0.5, (tl,650,'tear') 0.5, (tl,2200,'out') 1/3 within 1e-9, (tl,0,'money') 0, (tl,5000,'banner') 1; dimAlpha(0) 0, (300) 0.55, (1000) 0.55, (2250) 0.275, (2400) 0. dayEvents(tl,0,2400) is exactly [paper@300, coins@700, emit cash n 7 @700, stamp@1000] (floor(1400/200)=7; check the order of the two events at 700: sound first, emit second); dayEvents(tl,300,700) -> coins and emit only (300 is excluded, 700 is included); a negative delta (-1000): thud + emit rust n 6 (floor(5) -> min 6); zero delta: only paper and stamp. drawDayChange at ms 0 and 2400 draws nothing (0 calls); at ms 650 (tear 0.5, money not started): the first fillRect is [0,0,1280,720] with fillStyle 'rgba(20,16,42,0.550)', two calendar sheets (texts include 'DAY 2/365' and 'DAY 1/365') and the money text is '+£0'; at ms 1200 (tear done, money u 0.5, outCubic 0.875): one sheet only and the money text is '+£1,225' (round(1400*0.875)) drawn at (640,400) in fillStyle '#3FAE49'; a negative delta (-1000) at ms 1700 shows '-£1,000' in '#D9483B'; delta 0 draws no money text; with headline 'Big news' at ms 1500 some fillText starts with 'BIG' (the banner is typing) and without a headline there is no banner (no 1525-dot dither); all fillRects of the dim overlay lie inside the canvas."],
  accept=["`make test 2>&1 | grep 'PASS tests/daychange.test.mjs'` prints one line.", "`grep -nE 'Math.random|Date' src/ui/daychange.js` prints nothing.", NOEDIT],
  oos=["Wiring into the office/kettle tap (wave 2)."]),

 dict(id="GU20", title="iPhone safe areas: logical insets and boot hookup", needs=["GU01"],
  files=["src/ui/safearea.js", "src/boot.js", "index.html", "tests/safearea.test.mjs"],
  goal="Make the 1280x720 canvas respect notches and the home indicator: CSS `env(safe-area-inset-*)` -> logical-pixel insets after the letterbox is taken into account, published as `app.safe`, plus a physical-size helper for the text-size audit.",
  read=[GUD, "src/ui/canvas.js (`fitLayout(winW, winH)` -> {scale, offX, offY, viewW, viewH}; `LOGICAL_W/H`)", "src/boot.js (`bootGame`, `reapply`) and tests/boot.test.mjs (its fake window and document: they have NO getComputedStyle, so every new call must be guarded)", "index.html (already has viewport-fit=cover)", FK],
  steps=[
   "`src/ui/safearea.js` imports fitLayout, LOGICAL_W, LOGICAL_H from './canvas.js'. Export `logicalInsets(winW, winH, css)`: css = {top, right, bottom, left} in CSS pixels (missing -> 0). layout = fitLayout(winW, winH); each side: logical = Math.max(0, cssInset - letterboxOnThatSide)/layout.scale where the letterbox is offX for left and right and offY for top and bottom; return {top, right, bottom, left} (numbers, 0 when none). Export `safeRect(insets)` -> {x: left, y: top, w: 1280 - left - right, h: 720 - top - bottom}. Export `physicalPx(px, scale)` = px*scale (CSS px of a logical size) and `minLogicalPx(cssMin, scale)` = Math.ceil(cssMin/scale).",
   "`index.html`: inside the existing `<style>` add `:root { --sai-t: env(safe-area-inset-top, 0px); --sai-r: env(safe-area-inset-right, 0px); --sai-b: env(safe-area-inset-bottom, 0px); --sai-l: env(safe-area-inset-left, 0px); }`. `src/boot.js`: add a function `readCssInsets(win, doc)` that, only when `typeof win.getComputedStyle === 'function'` and `doc.documentElement` exists, reads the four custom properties with `getPropertyValue('--sai-t')` etc. and parseFloat (NaN -> 0), else returns all zeros; after `createApp` and inside `reapply()` set `app.safe = logicalInsets(win.innerWidth, win.innerHeight, readCssInsets(win, doc))` (app is created after the first reapply: set it right after createApp too). Do not change anything else in boot.js.",
   "`tests/safearea.test.mjs`: iPhone landscape 852x393 with css {top:0,right:59,bottom:21,left:59}: layout scale 393/720 = 0.5458333, viewW 698.67, offX 76.67; left/right insets are 0 (59 < 76.67) and bottom is 21/0.5458333 = 38.4733 (within 1e-3), top 0; a window 667x375 with all css 0 gives all zeros; a 1280x720 window with css {top:20,...:0} gives top 20; a window with no letterbox 1280x720 and left 50 gives left 50; missing css keys count as 0; safeRect({top:0,right:0,bottom:38.4733,left:0}) is {x:0,y:0,w:1280,h:681.5267} within 1e-3; physicalPx(22, 0.5458333) is 12.0083 within 1e-3; minLogicalPx(12, 0.5458333) is 22 and minLogicalPx(9, 0.5458333) is 17. Boot: in tests/boot.test.mjs style (do NOT edit that file; write one new test inside tests/safearea.test.mjs that imports bootGame and builds the fake window/canvas/document like boot.test.mjs does by copying its helper functions) check that after bootGame the returned app has `safe` with the four zero fields, and that adding `win.getComputedStyle = () => ({ getPropertyValue: (n) => n === '--sai-b' ? '21px' : '0px' })` and `documentElement: {}` on the fake doc gives safe.bottom close to 38.47 for innerWidth 852 and innerHeight 393 (fake devicePixelRatio 1)."],
  accept=["`make test 2>&1 | grep 'PASS tests/safearea.test.mjs'` prints one line.", "`make test 2>&1 | grep 'PASS tests/boot.test.mjs'` prints one line (existing boot tests stay green).", "`grep -c 'safe-area-inset' index.html` prints 4."],
  oos=["Any scene (they read app.safe in wave 2); src/ui/canvas.js."]),

 dict(id="GU21", title="kit_draw upgrade in place: textured panel, chunky button, animated-look bar, label outline", needs=["GU02", "GU05", "GU06", "GU07"],
  files=["src/ui/kit_draw.js", "tests/kit_draw_v2.test.mjs"],
  goal="Every scene gets the new look at once: `panel`, `button` and `bar` keep their names, arguments and the exact call patterns the old tests pin, but gain grain, highlights, the chunky pressed/hover button and the segmented bar. Also add an optional text outline and re-export the new helpers so scenes import from one place.",
  read=[GUD, "src/ui/kit_draw.js and tests/kit_draw.test.mjs (READ EVERY TEST: they pin behaviour that must stay)", "src/ui/panels2.js (GU05: grain, COLOR), src/ui/button2.js (GU06: drawButton2), src/ui/bars.js (GU07: drawBar2)", FK],
  steps=[
   "Edit `src/ui/kit_draw.js` only by ADDING and by these three exact changes. (a) `panel(ctx,x,y,w,h,opts)`: keep the existing rounded path, shadow, fill and border strokes exactly as they are (same fill/stroke counts, strokeStyle PALETTE.ink last); AFTER the stroke add, only when opts.grain !== false and bw > 0: fillStyle 'rgba(255,255,255,0.30)', fillRect(x + bw, y + bw, w - 2*bw, 2) (top highlight) and `grain(ctx, x+bw, y+bw, w-2*bw, h-2*bw, 'rgba(20,16,42,0.05)', 1/900, (x*31 + y*17) & 0xffff)` (import grain from './panels2.js'); these are fillRects, so `fill` counts do not change. (b) `button(ctx,b)`: replace the body by `drawButton2(ctx, b, {hover: b.hover === true, pressed: b.pressed === true})` (import from './button2.js'); keep the doc comment accurate. (c) `bar(...)`: replace the body by `drawBar2(ctx, x, y, w, h, value, max, color)` (import from './bars.js'); the call fillRect(x+2, y+2, (w-4)*frac, h-4) must still be produced.",
   "ADD to `label`: opts.outline (default false): when true, before the normal draw, fillStyle PALETTE.ink and fillText at the four offsets (x-2,y), (x+2,y), (x,y-2), (x,y+2) (drawn after the shadow, before the fill). Do not change the label's other behaviour or return value. At the bottom of the file add re-exports (no new imports of kit_draw into those modules, to avoid cycles): `export { drawIcon, ICON_NAMES } from './icons.js'; export { chunkyPanel, paperPanel, woodPanel, enamelSign } from './panels2.js'; export { fitOne, fitBlock, drawFitted, ellipsize, fitInRect } from './textfit.js'; export { drawButton2 } from './button2.js'; export { drawBar2, drawStatBar } from './bars.js';`.",
   "Run `make test` BEFORE writing new tests: every existing test must still pass; if a scene test fails because it counts `fillRect` calls exactly, fix the SCENE TEST's expectation only when the count is a pure count of calls (not a position) and say so in your summary, otherwise change the card's code so the old test passes. `tests/kit_draw_v2.test.mjs`: panel default makes the same `fill` count as before (1 shadow + 1 body = 2) and `stroke` count 1, plus at least 1 fillRect with fillStyle 'rgba(255,255,255,0.30)' of height 2 at [x+4, y+4, w-8, 2]; with {grain:false} no fillRect at all; the grain fillRect count equals Math.floor((w-8)*(h-8)/900) for panel(ctx,0,0,100,50); button 'GO' pressed:true draws its label 3px lower than the same button unpressed; button hot still sets strokeStyle PALETTE.lamp; disabled still uses PALETTE.midgrey and PALETTE.darkgrey; bar(ctx,10,10,100,20,5,10,'#f00') still contains fillRect [12,12,48,16]; label with outline:true draws 4 extra fillText calls in PALETTE.ink before the main one (count fillText 5 vs 1); the re-exports exist (typeof drawIcon, chunkyPanel, fitOne, drawButton2, drawBar2 are 'function')."],
  accept=["`make test` shows EVERY existing test file still PASS (list them if any needed a count fix) and `make test 2>&1 | grep 'PASS tests/kit_draw_v2.test.mjs'` prints one line.", "`make test 2>&1 | grep -c '^FAIL'` prints 0."],
  oos=["Any scene file; theme.js; tests other than counts noted above. Existing tests that stay green by design: kit_draw, theme, scenes, scene_* and the title/office/tvshop draw tests."]),

 dict(id="GU22", title="App wiring A: transitions, screen shake/flash and particles in createApp", needs=["GU13", "GU14", "GU15", "GU16"],
  files=["src/ui/scenes.js", "tests/app_fx.test.mjs"],
  goal="`createApp` learns to run transitions between screens, shake and flash on disasters, and draw particles, while behaving EXACTLY as before for any caller that does not use them.",
  read=[GUD, "src/ui/scenes.js (read all of it) and tests/scenes.test.mjs (every test must stay green)", "docs/SCENE_RULES.md", "src/ui/transitions.js, src/ui/transitions2.js, src/ui/screenfx.js, src/ui/particles.js (previous cards)", FK],
  steps=[
   "In `src/ui/scenes.js` import makeTransition/transDone/drawTransition from './transitions.js', drawStaticWipe/drawPageTurn from './transitions2.js', the screenfx functions and makeParticles/emit/updateParticles/drawParticles. In createApp add fields `fx: makeScreenFx()`, `particles: makeParticles(1)`, `transition: null`, `_lastDraw: null`. Add methods `shake(mag, ms)` (fxShake with app.now()), `flash(color, ms)`, `disaster()` (fxDisaster), `good()` (fxGood), `burst(kind, x, y, n)` (emit into app.particles). Change `push(id, params, opts)` and `go(id, params, opts)`: kind = opts && opts.transition !== undefined ? opts.transition : scene.enterTransition (a property wave-2 cards add to scenes; undefined for all existing scenes) ; when kind is a string and app.settings.fx !== false: BEFORE changing the stack, copy `from = app.stack.slice()`; do the normal change; then app.transition = {tr: makeTransition(kind, app.now()), from}. With no kind nothing changes at all.",
   "In `draw(ctx, t)`: keep the background fill; now = app.now(); dt = _lastDraw === null ? 0 : min(100, now - _lastDraw); _lastDraw = now; fxBegin(ctx, app.fx, now) before the scenes and fxEnd after the scenes (before toasts); define a private `drawStack(list)` that does the existing 'start at the top-most non-overlay scene' loop for any stack array. When app.transition is set and not done: call the matching draw function (drawStaticWipe for 'static', drawPageTurn for 'pageturn', else drawTransition) with drawFrom = () => drawStack(app.transition.from) and drawTo = () => drawStack(app.stack); when done set app.transition = null and draw normally. Then updateParticles(app.particles, dt) and drawParticles(ctx, app.particles) after the scenes, before the toasts. In `pointer` and `key`: return without doing anything while app.transition is set and not done. Everything else (toast code included) stays untouched in this card.",
   "`tests/app_fx.test.mjs` (a mutable clock: `let n = 0; createApp({now: () => n})`; register two tiny fake scenes that record draw calls): without a transition option go('a') then draw calls scene a's draw once and no translate/clip; `app.push('b', null, {transition:'slide-left'})` followed by draw at n = 175 (u 0.5) calls a's draw and b's draw once each, with translate [-1120,0] and [160,0] seen in ctx.calls; at n = 400 (done) only b is drawn and app.transition is null; pointer('down',1,1) during the transition does not reach scene b (b.pointer never called) and after it does; `scene.enterTransition = 'fade'` on b is honoured when no opts are given; with app.settings.fx === false no transition starts; 'static' and 'pageturn' go through their draw functions (the ctx shows 32x32 fillRects for static at u 0.25; a scale call for pageturn); app.disaster() at n=0 then draw at n=0 contains a fillRect [0,0,1280,720] with a red 'rgba(217,72,59,' fillStyle; app.burst('confetti', 100, 100, 5) then draw at n = 0 and again at n = 100 shows 5 confetti fillRects of height 6 both times; dt is capped (a draw 5000 ms later moves particles by at most 100 ms of physics); the existing tests/scenes.test.mjs passes unchanged."],
  accept=["`make test 2>&1 | grep 'PASS tests/app_fx.test.mjs'` prints one line.", "`make test 2>&1 | grep 'PASS tests/scenes.test.mjs'` prints one line (all existing app tests stay green).", "`make test 2>&1 | grep -c '^FAIL'` prints 0."],
  oos=["Toasts, CRT, banner and HUD (GU23); any scene file."]),

 dict(id="GU23", title="App wiring B: toast v2, tooltip, CRT overlay and safe insets in createApp", needs=["GU17", "GU18", "GU20", "GU21", "GU22"],
  files=["src/ui/scenes.js", "tests/scenes.test.mjs", "tests/app_overlays.test.mjs"],
  goal="Finish the app shell: toasts get an icon, slide-in and fade-out (same place on screen when settled); a tooltip slot; the CRT filter really turns on when the setting is on; `app.safe` exists with zero defaults.",
  read=[GUD, "src/ui/scenes.js and tests/scenes.test.mjs (the toast tests are at the end of the file)", "src/ui/overlays.js (GU18)", "src/ui/crt.js (GU17)", "src/ui/safearea.js (GU20)", FK],
  steps=[
   "In `src/ui/scenes.js`: `toast(text, ms, kind)`: push {text, until: now + dur, born: now, kind} (the old fields `text` and `until` keep their exact meaning, so `app.toasts[0].until` is still now + 2500 by default). In draw replace the toast loop by `drawToast2(ctx, live[i], nowMs, i, panel)` (import panel from './kit_draw.js'; drawToast2 from './overlays.js'). Add `safe: {top:0, right:0, bottom:0, left:0}` to the app object. Add `tooltip: makeTooltip()` and a method `hover(id, text, x, y)` that calls ttHover and stores {text, x, y} in app._tip (or clears it when id is null); at the end of draw (after toasts) when ttVisible(app.tooltip, now) and app._tip: drawTooltip(ctx, app._tip.text, app._tip.x, app._tip.y). Last of all in draw: when app.settings.crt === true call drawCrt(ctx, app.w, app.h, t).",
   "Update the ONE existing test in `tests/scenes.test.mjs` named 'toast panel is 560 wide centred horizontally near y 640': the toast now slides in, so draw it settled: use `let n = 0; const app = createApp({now: () => n}); app.toast('hi'); n = 1000; ... app.draw(ctx, 0)` and keep the moveTo(370, 640) assertion. Change nothing else in that file. Then `tests/app_overlays.test.mjs`: app.toast('x') gives toasts[0] with keys text, until, born, kind (kind undefined) and until === now + 2500; app.toast('x', 500, 'good') has kind 'good'; a 'good' toast draws tick icon fillRects; at now = born the toast is drawn 40px lower (the panel path starts at moveTo(370, 680)) with globalAlpha 0 set; expired toasts are removed exactly as before; `app.safe` equals {top:0,right:0,bottom:0,left:0}; app.hover('btn','Buy it',640,300) then draw at now 0: no tooltip text; draw at now 400: 'Buy it' is drawn; app.hover(null) clears it; settings.crt true adds exactly one `stroke` from the CRT scanline path with strokeStyle 'rgba(0,0,0,0.1)' as the last stroke and false adds none; the other tests in scenes.test.mjs still pass."],
  accept=["`make test 2>&1 | grep 'PASS tests/app_overlays.test.mjs'` prints one line.", "`make test 2>&1 | grep 'PASS tests/scenes.test.mjs'` prints one line.", "`make test 2>&1 | grep -c '^FAIL'` prints 0."],
  oos=["Any scene file; the banner and HUD strip are drawn by scenes themselves (GU24), not by the app."]),

 dict(id="GU24", title="Office in the RSAMH frame: speech banner on top, HUD strip at the bottom", needs=["GU03", "GU07", "GU08", "GU11", "GU21"],
  files=["src/ui/scenes/office.js", "tests/scene_office_rsamh.test.mjs"],
  goal="First scene wearing the new chrome: Dave's one line a day moves from the small bubble into the top speech banner (tail pointing at Dave), the old top HUD is replaced by the bottom HUD strip with an animated cash counter and the torn-off calendar day, and the four plate taps move to the new plate icons. The room art is NOT moved yet (it keeps its own layout; the banner and strip simply cover its top 8-112 px and bottom 590-720 px until the art team's 1280x470 tableau lands).",
  read=[GUD, "src/ui/scenes/office.js (read all) and tests/scene_office.test.mjs (every test must stay green; note it taps `LAYOUT.hits.fatcat/stable/household/hammer` and expects the toasts, expects text '£20,000' and a text starting 'DAY 1', and counts `stroke` calls relative to each other)", "src/ui/banner.js (GU08), src/ui/hudstrip.js (GU11), src/ui/hudparts.js (GU09: PLATE_SLOTS), src/ui/anim.js (GU07: makeCounter, counterSet, counterValue)", "src/art/officelayout.js (OFFICE.dave etc.)"],
  steps=[
   "In `src/ui/scenes/office.js`: stop importing `drawHud`, `PLATE_RECTS` and `speechBubble`; import `drawBanner` from '../banner.js', `drawHudStrip` from '../hudstrip.js', `PLATE_SLOTS` from '../hudparts.js', `makeCounter, counterSet, counterValue` from '../anim.js'. The four plate hits now use PLATE_SLOTS (same keys, same toast text via PLATE_INFO), and in the exported `LAYOUT.hits` the entries fatcat, stable, household, hammer point at PLATE_SLOTS[0..3] (so the existing test taps the new rects). Keep every other hit, the TAP RULE code, `dayLine` caching and the keyboard handler exactly as they are.",
   "In `draw`: keep everything up to Dave and Mark. Replace the `speechBubble(...)` call by `drawBanner(ctx, this.dayLine.line, {tailX: OFFICE.dave.x + 48, tailY: OFFICE.dave.y + 20, reveal: <typewriter fraction>})` where the fraction is clamp01((nowMs - this.lineSince) * 40 / 1000 / Math.max(1, this.dayLine.line.length)) and `this.lineSince` is set to nowMs whenever the cached line changes (nowMs = typeof app.now === 'function' ? app.now() : app.now). Draw the banner AFTER the hotspot glows so it covers art, and the HUD strip last: replace `drawHud(ctx, state, t)` by `drawHudStrip(ctx, state, {cashShown: counterValue(this.cashCounter, nowMs), portrait: null, nowMs, dayChangedAt: app.dayChangedAt, prevDay: day - 1}, t)`. `this.cashCounter = makeCounter(state.cash)` is created in `enter` (and lazily in draw when missing); in draw call `counterSet(this.cashCounter, state.cash, nowMs)` only when state.cash differs from this.lastCash (then store lastCash) so the figure counts up over 700 ms. The strip's calendar sheet makes the old wall-calendar prop redundant but keep drawing it (its hit and test remain).",
   "`tests/scene_office_rsamh.test.mjs` (same fake app and startGame(3) as scene_office.test.mjs; the fake app clock is a number: set `app.now = () => 5000` for time-based checks): the office draw includes the banner text uppercased (the day-1 line from chatterFor({rng: 1*7919+13}, 'newmonth').toUpperCase(), fully revealed when lineSince is far in the past: set officeScene.lineSince = -100000 after the first draw, or draw twice with now 0 then 100000) and no longer calls drawHud (no fillText 'REP 40' and no 'BUZZ 0'); texts include '£20,000' and 'DAY 1/365'; the first fillRect of the strip [0,590,1280,130] is present; tapping the centre of LAYOUT.hits.fatcat toasts 'Fat Cat...' exactly as before and LAYOUT.hits.fatcat equals {key:'fatcat', x:24, y:600, w:48, h:48}; the cash counter: after state.cash changes from 20000 to 21000 at now 5000 the shown figure at now 5350 is '£20,875'... compute exactly: round(20000 + 1000*outCubic(0.5)) = 20875; at 5700 it is '£21,000'; two draws with an unchanged cash do not restart the counter; the audit helper tests/uiaudit.js (GU03) on the HUD strip region only: filter the entries with y0 >= 590 and require none below the floor and no overlaps among them."],
  accept=["`make test 2>&1 | grep 'PASS tests/scene_office_rsamh.test.mjs'` prints one line.", "`make test 2>&1 | grep -E 'PASS tests/(scene_office|office_art|hud|playthrough).test.mjs'` prints 4 lines (existing office, art, hud and playthrough tests stay green).", "`make test 2>&1 | grep -c '^FAIL'` prints 0."],
  oos=["src/art/*.js (room art, hud.js, speech.js stay as they are), OFFICE rectangles, every other scene."]),

 dict(id="GU25", title="TV shop fixes: quip off the car, CONDITION label, tag text size, button gaps", needs=["GU02", "GU03", "GU21"],
  files=["src/ui/scenes/tvshop.js", "tests/scene_tvshop_layout.test.mjs"],
  goal="Fix what Lee saw: the salesman's quip is painted over the car, `CONDITION 3.3/10` is clipped by its own bar, FOR SALE / TO RENT tag text is only 12px, and BUY / RENT touch the detail panel. Prove it with numbers (text boxes, rectangles), and show the pattern the other scenes will copy in wave 2.",
  read=[GUD, "src/ui/scenes/tvshop.js (read all) and tests/scene_tvshop_draw.test.mjs + tests/scene_tvshop_input.test.mjs (they stay green: the title 'WEBB TV SHOPPING', car names, money(price), the blinking '>' cursor exactly once at t=0, STYLE/UPKEEP/GRIT and a text containing 'CONDITION', taps on LAYOUT.buy/rent/back and rows)", "src/ui/textfit.js (GU02: fitBlock, fitOne, fitInRect), tests/uiaudit.js (GU03: auditCtx, rectsOverlap)", "src/art/profiles.js (`profileOf(arch)`: lengthPx and the part points: car height in px = max y over body points * lengthPx / 100 * scale)"],
  steps=[
   "In `tvshop.js` change `LAYOUT`: buy {x:640, y:608, w:290, h:60}, rent {x:950, y:608, w:290, h:60}; add `quip: {x:640, y:168, w:580, h:64}` and `stage: {x:640, y:236, w:580, h:154}` (rows of stat bars now start at y 396). Row tag (drawRow): panel w 140 at tagX = L.x + 236, label size 16 title font, centred; car name `maxW` 190; price maxW 160. Detail: the name stays at D.y+16; the quip is drawn with `drawFitted`/fitBlock into LAYOUT.quip (kind body, maxPx 28, minPx 22, maxLines 2, color ink) instead of `paragraph`; the car is drawn inside LAYOUT.stage: profile = profileOf(model.archetype); srcW = profile.lengthPx, srcH = (max y of the body part points) * profile.lengthPx/100 (scale 1); f = fitInRect(srcW, srcH, LAYOUT.stage, {maxScale: 1.15, pad: 6}); drawCar(ctx, model.archetype, f.x, f.y, f.scale, {...same options as before}).",
   "Stat rows: first row y 396, step 40. Label column: `label(ctx, text, D.x+20, y, {size:26, maxW:150})`; bar at (D.x+180, y+4, 330, 22) via the kit `bar`; the value text right-aligned at x = D.x + D.w - 20: `oneDp(v) + '/10'` for all four rows, size 26, maxW 70. The fourth row's label is exactly 'CONDITION' (the number moved to the right column; the existing test only needs a text containing 'CONDITION'). The 'Owner:' row follows at y + 40 as before.",
   "`tests/scene_tvshop_layout.test.mjs` (setup copied from scene_tvshop_draw.test.mjs: `startGame(5)`, `tvshopScene.enter(app)`; loop `selected` over every listing, sale and rent): using `auditCtx` from tests/uiaudit.js on a fresh makeCtx per draw: `belowFloor.length === 0`, `offCanvas.length === 0`, `overlaps.length === 0` (list the offenders with describe() in the failure message; the list rows are clipped by ctx.clip to LAYOUT.list, so before auditing drop any entry whose y0 >= LAYOUT.list.y + LAYOUT.list.h or whose y1 <= LAYOUT.list.y); LAYOUT.quip bottom (y + h) <= LAYOUT.stage.y and LAYOUT.stage bottom <= 396; every quip text line fillText y is >= quip.y and < quip.y + quip.h; the drawCar ground point (the first `translate` after a save whose args are the car position: check via ctx.calls: translate x within the stage and y <= stage.y + stage.h - 6 + 0.001) and the car's scaled height f.h <= stage.h - 12; buy and rent rects: buy.y >= detail.y + detail.h + 6 (LAYOUT.detail.y + LAYOUT.detail.h is 600, so buy.y 608 gives an 8px gap) and rent.x - (buy.x + buy.w) is 20; the 'FOR SALE' tag text is drawn at 16px title (parse px from the font set before it) and fits in its 140px tag: 8*16 = 128 <= 140; the existing scene_tvshop tests pass unchanged."],
  accept=["`make test 2>&1 | grep 'PASS tests/scene_tvshop_layout.test.mjs'` prints one line.", "`make test 2>&1 | grep -E 'PASS tests/scene_tvshop_(draw|input).test.mjs'` prints 2 lines.", "`make test 2>&1 | grep -c '^FAIL'` prints 0."],
  oos=["Other scenes (wave 2 applies the same pattern: auction lot title vs car, advert RISK lines, garage empty state, endgame confetti via particles)."]),
]
